)

func main() {
    // \d+ matches one or more digits
    digitRe := regexp.MustCompile(`\d+`)
    fmt.Println(digitRe.FindString("Order #12345")) // 12345

    // \w+ matches word characters
    wordRe := regexp.MustCompile(`\w+`)
    fmt.Println(wordRe.FindAllString("Hello, World!", -1)) // [Hello World]

    // . matches any character
    dotRe := regexp.MustCompile(`h.t`)
    fmt.Println(dotRe.FindAllString("hat hot hit hut", -1)) // [hat hot hit hut]

    // Character class [aeiou] matches vowels
    vowelRe := regexp.MustCompile(`[aeiou]`)
    fmt.Println(vowelRe.FindAllString("hello", -1)) // [e o]

    // Quantifiers
    fmt.Println(regexp.MustCompile(`a+`).FindString("caaandy"))   // aaa
    fmt.Println(regexp.MustCompile(`a*`).FindString("caaandy"))   // (empty - matches zero a's at start)
    fmt.Println(regexp.MustCompile(`a?`).FindString("caaandy"))   // (empty - matches zero a's at start)
    fmt.Println(regexp.MustCompile(`a{2,3}`).FindString("caaandy")) // aaa
}

