import (
    "fmt"
    "strings"
)

type LogLevel int

const (
    LevelDebug LogLevel = iota
    LevelInfo
    LevelWarn
    LevelError
)

func (l LogLevel) String() string {
    switch l {
    case LevelDebug:
        return "DEBUG"
    case LevelInfo:
        return "INFO"
    case LevelWarn:
        return "WARN"
    case LevelError:
        return "ERROR"
    default:
        return fmt.Sprintf("LogLevel(%d)", l)
    }
}

// Parse string to LogLevel
var levelMap = map[string]LogLevel{
    "debug": LevelDebug,
    "info":  LevelInfo,
    "warn":  LevelWarn,
    "error": LevelError,
}

func ParseLogLevel(s string) (LogLevel, error) {
    level, ok := levelMap[strings.ToLower(s)]
    if !ok {
        return 0, fmt.Errorf("invalid log level: %q", s)
    }
    return level, nil
}

func main() {
    // Parse from string
    level, err := ParseLogLevel("WARN")
    if err != nil {
        fmt.Println("Error:", err)
        return
    }
    fmt.Println("Parsed level:", level) // WARN

    // Invalid level
    _, err = ParseLogLevel("verbose")
    if err != nil {
        fmt.Println("Error:", err) // invalid log level: "verbose"
    }

    // Use in logging
    currentLevel := LevelInfo
    messages := []struct {
        level LogLevel
        msg   string
    }{
        {LevelDebug, "Debugging info"},
        {LevelInfo, "Server started"},
        {LevelWarn, "High memory usage"},
        {LevelError, "Connection failed"},
    }

    fmt.Println("\nLogs (current level:", currentLevel, "):")
    for _, m := range messages {
        if m.level >= currentLevel {
            fmt.Printf("[%s] %s\n", m.level, m.msg)
        }
    }
}

