    fmt.Printf("bit2=%d mask2=%d\n", bit2, mask2)
    fmt.Printf("bit3=%d mask3=%d\n", bit3, mask3)

    fmt.Println("\nSkipped values:")
    fmt.Println("A =", A) // 0
    fmt.Println("B =", B) // 1
    fmt.Println("C =", C) // 4
}

