    fmt.Println("Joined path:", configPath)

    // Split into directory and file
    dir, file := filepath.Split(configPath)
    fmt.Printf("Dir: %q, File: %q\n", dir, file)

    // Get just the filename
    base := filepath.Base(configPath)
    fmt.Println("Base:", base)

    // Get just the directory
    dirOnly := filepath.Dir(configPath)
    fmt.Println("Dir:", dirOnly)

    // Get extension
    ext := filepath.Ext(configPath)
    fmt.Println("Extension:", ext)

    // Remove extension
    withoutExt := configPath[:len(configPath)-len(ext)]
    fmt.Println("Without ext:", withoutExt)

    // Get absolute path
    absPath, err := filepath.Abs("relative/path/file.txt")
    if err == nil {
        fmt.Println("Absolute:", absPath)
    }

    // Match patterns
    matched, _ := filepath.Match("*.json", "settings.json")
    fmt.Println("*.json matches settings.json:", matched)
}

