import (
    "fmt"
    "io"
    "os"
)

// copyFile copies a file from src to dst
func copyFile(src, dst string) error {
    source, err := os.Open(src)
    if err != nil {
        return err
    }
    defer source.Close()

    dest, err := os.Create(dst)
    if err != nil {
        return err
    }
    defer dest.Close()

    _, err = io.Copy(dest, source)
    return err
}

func main() {
    // Create original file
    os.WriteFile("original.txt", []byte("Original content"), 0644)

    // Copy file
    err := copyFile("original.txt", "copy.txt")
    if err != nil {
        fmt.Println("Copy error:", err)
        return
    }
    fmt.Println("Copied original.txt to copy.txt")

    // Rename/move file
    err = os.Rename("copy.txt", "renamed.txt")
    if err != nil {
        fmt.Println("Rename error:", err)
        return
    }
    fmt.Println("Renamed copy.txt to renamed.txt")

    // Verify
    content, _ := os.ReadFile("renamed.txt")
    fmt.Println("Content:", string(content))

    // Clean up
    os.Remove("original.txt")
    os.Remove("renamed.txt")
}

