import "testing"

// Allocates new slice each call
func makeSlice(n int) []int {
    s := make([]int, n)
    for i := 0; i < n; i++ {
        s[i] = i
    }
    return s
}

// Reuses provided slice
func fillSlice(s []int) {
    for i := range s {
        s[i] = i
    }
}

// Sink prevents compiler from optimizing away results
var sink []int

func BenchmarkMakeSlice(b *testing.B) {
    b.ReportAllocs()
    for i := 0; i < b.N; i++ {
        sink = makeSlice(1000)
    }
}

func BenchmarkFillSlice(b *testing.B) {
    b.ReportAllocs()
    s := make([]int, 1000) // Allocate once
    b.ResetTimer()         // Don't count setup allocation
    for i := 0; i < b.N; i++ {
        fillSlice(s)
    }
    sink = s // Use result
}

