func merge(ch1, ch2 <-chan int) <-chan int {
	out := make(chan int)

	go func() {
		defer close(out)

		for ch1 != nil || ch2 != nil {
			select {
			case v, ok := <-ch1:
				if !ok {
					ch1 = nil // Disable when closed
				} else {
					out <- v
				}
			case v, ok := <-ch2:
				if !ok {
					ch2 = nil // Disable when closed
				} else {
					out <- v
				}
			}
		}
	}()

	return out
}

