	fmt.Printf("GOMAXPROCS: %d\n", runtime.GOMAXPROCS(0)) // 0 = query only

	// Get number of CPUs
	fmt.Printf("NumCPU: %d\n", runtime.NumCPU())

	// Set GOMAXPROCS (returns previous value)
	old := runtime.GOMAXPROCS(4)
	fmt.Printf("Changed from %d to 4\n", old)

	// Number of goroutines currently running
	fmt.Printf("NumGoroutine: %d\n", runtime.NumGoroutine())
