package main

import (
	"fmt"
	"runtime"
)

func main() {
	runtime.GOMAXPROCS(1) // Force single P

	// Before Go 1.14, this would block forever
	// because the loop has no scheduling points.
	// Since Go 1.14, async preemption rescues it.

	go func() {
		fmt.Println("goroutine started")
		// Tight loop with no function calls
		for i := 0; ; i++ {
			_ = i * i // No scheduling point here
		}
	}()

	// In Go 1.14+, this eventually prints
	// because the runtime preempts the tight loop
	for i := 0; i < 5; i++ {
		runtime.Gosched() // Yield to scheduler
		fmt.Printf("main: iteration %d\n", i)
	}
}

