func main() {
	runtime.GOMAXPROCS(1) // Single P for demonstration

	var wg sync.WaitGroup
	wg.Add(2)

	go func() {
		defer wg.Done()
		for i := 0; i < 3; i++ {
			fmt.Println("A:", i)
			runtime.Gosched() // Yield to let B run
		}
	}()

	go func() {
		defer wg.Done()
		for i := 0; i < 3; i++ {
			fmt.Println("B:", i)
			runtime.Gosched() // Yield to let A run
		}
	}()

	wg.Wait()

	// Output (interleaved due to Gosched):
	// A: 0
	// B: 0
	// A: 1
	// B: 1
	// A: 2
	// B: 2
}

package main

import (
	"fmt"
	"runtime"
	"sync"
)

func main() {
	var wg sync.WaitGroup
	wg.Add(1)

	go func() {
		defer wg.Done()

		// Lock this goroutine to its OS thread
		runtime.LockOSThread()
		defer runtime.UnlockOSThread()

		// Now this goroutine will ONLY run on this OS thread.
		// Useful for:
		// - C libraries with thread-local state
		// - OpenGL contexts (must stay on same thread)
		// - Windows COM objects

		fmt.Println("Running on locked thread")

		// If you don't call UnlockOSThread, the thread
		// is destroyed when the goroutine exits.
	}()

	wg.Wait()
}

// Query and set GOMAXPROCS
runtime.GOMAXPROCS(0)  // Query current value
runtime.GOMAXPROCS(4)  // Set to 4, returns old value

// Query runtime info
