runtime.NumGoroutine() // Current goroutine count

// Scheduler hints
runtime.Gosched()        // Yield processor to other goroutines
runtime.LockOSThread()   // Pin goroutine to OS thread
runtime.UnlockOSThread() // Release thread pinning

