func (c Counter) IncrementWrong() {
    c.Value++ // This modifies the copy, not the original!
}

// RIGHT: Pointer receiver modifies original
func (c *Counter) Increment() {
    c.Value++ // This modifies the actual Counter
}

// Read-only method: value receiver is perfectly fine
func (c Counter) IsZero() bool {
    return c.Value == 0
}

