func (l *List) Sum() int {
    if l == nil {
        return 0 // Base case: empty list
    }
    return l.Value + l.Next.Sum() // Recursive call
}

// Also safe: returns sensible value for nil
func (l *List) Length() int {
    if l == nil {
        return 0
    }
    return 1 + l.Next.Length()
}

func main() {
    // Nil list - methods handle this gracefully
    var empty *List = nil
    fmt.Println("Empty sum:", empty.Sum())     // 0 (no panic!)
    fmt.Println("Empty length:", empty.Length()) // 0

    // Build a small list: 1 -> 2 -> 3 -> nil
    list := &List{Value: 1, Next: &List{Value: 2, Next: &List{Value: 3}}}
    fmt.Println("List sum:", list.Sum())       // 6
    fmt.Println("List length:", list.Length()) // 3
}

