        return fmt.Sprintf("#%d", n)
    })
    fmt.Println("Mapped:", strs)

    // Filter even numbers
    evens := Filter(nums, func(n int) bool {
        return n%2 == 0
    })
    fmt.Println("Evens:", evens)

    // Pair with different types
    p := Pair[string, int]{Key: "age", Value: 30}
    fmt.Printf("Pair: %s = %d\n", p.Key, p.Value)
}

