// Result is a concrete type we return
type Result struct {
    Lines int
    Words int
    Chars int
}

// Analyze accepts io.Reader (interface) for flexibility
// Returns *Result (concrete type) for clarity
func Analyze(r io.Reader) (*Result, error) {
    data, err := io.ReadAll(r)
    if err != nil {
        return nil, err
    }

    text := string(data)
    return &Result{
        Lines: strings.Count(text, "\n") + 1,
        Words: len(strings.Fields(text)),
        Chars: len(text),
    }, nil
}

func main() {
    // strings.Reader satisfies io.Reader
    text := "Hello world\nThis is Go"
    reader := strings.NewReader(text)

    result, err := Analyze(reader)
    if err != nil {
        fmt.Println("Error:", err)
        return
    }

    fmt.Printf("Lines: %d, Words: %d, Chars: %d\n",
        result.Lines, result.Words, result.Chars)
}

