import "fmt"

type DataSource interface {
    GetData() string
}

// Base implementation
type FileDataSource struct {
    filename string
}

func (f FileDataSource) GetData() string {
    return fmt.Sprintf("[data from %s]", f.filename)
}

// Decorator: adds logging
type LoggingDecorator struct {
    DataSource  // Embed the interface
    prefix string
}

func (l LoggingDecorator) GetData() string {
    fmt.Printf("%s: Fetching data...\n", l.prefix)
    data := l.DataSource.GetData()  // Delegate
    fmt.Printf("%s: Got %d bytes\n", l.prefix, len(data))
    return data
}

// Another decorator: adds caching
type CachingDecorator struct {
    DataSource
    cache string
}

func (c *CachingDecorator) GetData() string {
    if c.cache != "" {
        fmt.Println("Cache hit!")
        return c.cache
    }
    fmt.Println("Cache miss, fetching...")
    c.cache = c.DataSource.GetData()
    return c.cache
}

func main() {
    // Base source
    file := FileDataSource{filename: "users.json"}

    // Wrap with logging
    logged := LoggingDecorator{DataSource: file, prefix: "LOG"}
    fmt.Println("Result:", logged.GetData())

    fmt.Println("---")

    // Stack decorators: caching on top of logging
    cached := &CachingDecorator{DataSource: logged}
    fmt.Println("First call:")
    cached.GetData()
    fmt.Println("Second call:")
    cached.GetData()
}

