    "fmt"
)

type Server struct {
    port    int
    timeout int
}

// Option returns an error if validation fails
type Option func(*Server) error

func WithPort(port int) Option {
    return func(s *Server) error {
        if port < 1 || port > 65535 {
            return fmt.Errorf("invalid port: %d", port)
        }
        s.port = port
        return nil
    }
}

func WithTimeout(timeout int) Option {
    return func(s *Server) error {
        if timeout < 1 {
            return errors.New("timeout must be positive")
        }
        s.timeout = timeout
        return nil
    }
}

func NewServer(opts ...Option) (*Server, error) {
    s := &Server{port: 8080, timeout: 30}

    for _, opt := range opts {
        if err := opt(s); err != nil {
            return nil, err
        }
    }

    return s, nil
}

func main() {
    // Valid options
    s1, err := NewServer(WithPort(9000))
    if err != nil {
        fmt.Println("Error:", err)
    } else {
        fmt.Printf("Server: port=%d, timeout=%d\n", s1.port, s1.timeout)
    }

    // Invalid port
    _, err = NewServer(WithPort(70000))
    fmt.Println("Invalid port error:", err)

    // Invalid timeout
    _, err = NewServer(WithTimeout(-5))
    fmt.Println("Invalid timeout error:", err)
}

