import "fmt"

// Storage is the interface callers use
type Storage interface {
    Save(key string, data []byte) error
    Load(key string) ([]byte, error)
}

// Concrete implementations
type MemoryStorage struct {
    data map[string][]byte
}

func (m *MemoryStorage) Save(key string, data []byte) error {
    m.data[key] = data
    return nil
}

func (m *MemoryStorage) Load(key string) ([]byte, error) {
    if data, ok := m.data[key]; ok {
        return data, nil
    }
    return nil, fmt.Errorf("key not found: %s", key)
}

type FileStorage struct {
    basePath string
}

func (f *FileStorage) Save(key string, data []byte) error {
    fmt.Printf("[FileStorage] Would save to %s/%s\n", f.basePath, key)
    return nil
}

func (f *FileStorage) Load(key string) ([]byte, error) {
    fmt.Printf("[FileStorage] Would load from %s/%s\n", f.basePath, key)
    return []byte("file data"), nil
}

// Factory function - returns interface, hides implementation
func NewStorage(storageType string) Storage {
    switch storageType {
    case "file":
        return &FileStorage{basePath: "/data"}
    case "memory":
        fallthrough
    default:
        return &MemoryStorage{data: make(map[string][]byte)}
    }
}

func main() {
    // Caller doesn't know the concrete type
    memStore := NewStorage("memory")
    memStore.Save("key1", []byte("hello"))
    data, _ := memStore.Load("key1")
    fmt.Println("Memory:", string(data))

    fileStore := NewStorage("file")
    fileStore.Save("key2", []byte("world"))
    data, _ = fileStore.Load("key2")
    fmt.Println("File:", string(data))
}

