import "fmt"

type Query struct {
    table   string
    columns []string
    where   string
    orderBy string
    limit   int
}

type QueryBuilder struct {
    query Query
}

func NewQueryBuilder() *QueryBuilder {
    return &QueryBuilder{}
}

func (b *QueryBuilder) Select(columns ...string) *QueryBuilder {
    b.query.columns = columns
    return b
}

func (b *QueryBuilder) From(table string) *QueryBuilder {
    b.query.table = table
    return b
}

func (b *QueryBuilder) Where(condition string) *QueryBuilder {
    b.query.where = condition
    return b
}

func (b *QueryBuilder) OrderBy(column string) *QueryBuilder {
    b.query.orderBy = column
    return b
}

func (b *QueryBuilder) Limit(n int) *QueryBuilder {
    b.query.limit = n
    return b
}

func (b *QueryBuilder) Build() Query {
    return b.query
}

func (q Query) String() string {
    sql := "SELECT "
    if len(q.columns) > 0 {
        for i, c := range q.columns {
            if i > 0 {
                sql += ", "
            }
            sql += c
        }
    } else {
        sql += "*"
    }
    sql += " FROM " + q.table
    if q.where != "" {
        sql += " WHERE " + q.where
    }
    if q.orderBy != "" {
        sql += " ORDER BY " + q.orderBy
    }
    if q.limit > 0 {
        sql += fmt.Sprintf(" LIMIT %d", q.limit)
    }
    return sql
}

func main() {
    // Fluent API for building queries
    query1 := NewQueryBuilder().
        Select("name", "email").
        From("users").
        Where("active = true").
        OrderBy("name").
        Limit(10).
        Build()
    fmt.Println(query1)

    // Simpler query
    query2 := NewQueryBuilder().
        From("products").
        Where("price > 100").
        Build()
    fmt.Println(query2)
}

