import "fmt"

// Shape calculates area
type Shape interface {
    SetWidth(w int)
    SetHeight(h int)
    Area() int
}

type Rectangle struct {
    width, height int
}

func (r *Rectangle) SetWidth(w int)  { r.width = w }
func (r *Rectangle) SetHeight(h int) { r.height = h }
func (r *Rectangle) Area() int       { return r.width * r.height }

// Square tries to be a Rectangle - LSP VIOLATION
type Square struct {
    side int
}

func (s *Square) SetWidth(w int)  { s.side = w }  // Also changes "height"
func (s *Square) SetHeight(h int) { s.side = h }  // Also changes "width"
func (s *Square) Area() int       { return s.side * s.side }

// This function expects Rectangle behavior
func DoubleWidth(s Shape) {
    s.SetWidth(s.Area() / 10)  // Some operation
    s.SetHeight(10)
    // Expects: width changed, height is 10
}

func main() {
    rect := &Rectangle{width: 5, height: 10}
    fmt.Printf("Rectangle before: %dx%d = %d\n", rect.width, rect.height, rect.Area())
    DoubleWidth(rect)
    fmt.Printf("Rectangle after: %dx%d = %d\n", rect.width, rect.height, rect.Area())

    square := &Square{side: 5}
    fmt.Printf("Square before: side=%d, area=%d\n", square.side, square.Area())
    DoubleWidth(square)  // Unexpected behavior!
    fmt.Printf("Square after: side=%d, area=%d\n", square.side, square.Area())
    // Width and height aren't independent - LSP violated
}

