import "fmt"

// Small, focused interfaces
type Reader interface {
    Read(id string) ([]byte, error)
}

type Writer interface {
    Create(data []byte) (string, error)
    Update(id string, data []byte) error
}

type Deleter interface {
    Delete(id string) error
}

// Compose when needed
type ReadWriter interface {
    Reader
    Writer
}

// ReadOnlyCache only implements what it can do
type ReadOnlyCache struct {
    data map[string][]byte
}

func (c *ReadOnlyCache) Read(id string) ([]byte, error) {
    if data, ok := c.data[id]; ok {
        return data, nil
    }
    return nil, fmt.Errorf("not found: %s", id)
}

// Database implements everything
type Database struct {
    data   map[string][]byte
    nextID int
}

func (d *Database) Read(id string) ([]byte, error) {
    if data, ok := d.data[id]; ok {
        return data, nil
    }
    return nil, fmt.Errorf("not found: %s", id)
}

func (d *Database) Create(data []byte) (string, error) {
    d.nextID++
    id := fmt.Sprintf("id_%d", d.nextID)
    d.data[id] = data
    return id, nil
}

func (d *Database) Update(id string, data []byte) error {
    d.data[id] = data
    return nil
}

func (d *Database) Delete(id string) error {
    delete(d.data, id)
    return nil
}

// Functions accept minimal interface
func FetchData(r Reader, id string) {
    data, err := r.Read(id)
    if err != nil {
        fmt.Println("Error:", err)
        return
    }
    fmt.Printf("Data: %s\n", data)
}

func main() {
    cache := &ReadOnlyCache{data: map[string][]byte{"key1": []byte("cached value")}}
    db := &Database{data: make(map[string][]byte)}

    // Both work with FetchData - it only needs Reader
    FetchData(cache, "key1")

    id, _ := db.Create([]byte("new record"))
    FetchData(db, id)
}

