// Mock repository for testing
type MockUserRepo struct {
    Users     map[string]*User
    FindCalls []string
    SaveCalls []*User
    FindErr   error
    SaveErr   error
}

func (m *MockUserRepo) FindByID(ctx context.Context, id string) (*User, error) {
    m.FindCalls = append(m.FindCalls, id)
    if m.FindErr != nil {
        return nil, m.FindErr
    }
    if user, ok := m.Users[id]; ok {
        return user, nil
    }
    return nil, errors.New("not found")
}

func (m *MockUserRepo) Save(ctx context.Context, user *User) error {
    m.SaveCalls = append(m.SaveCalls, user)
    if m.SaveErr != nil {
        return m.SaveErr
    }
    m.Users[user.ID] = user
    return nil
}

func TestUserService_UpdateEmail(t *testing.T) {
    tests := []struct {
        name      string
        userID    string
        newEmail  string
        setup     func(*MockUserRepo)
        wantErr   bool
        wantEmail string
    }{
        {
            name:     "successful update",
            userID:   "1",
            newEmail: "new@example.com",
            setup: func(m *MockUserRepo) {
                m.Users["1"] = &User{ID: "1", Name: "Test", Email: "old@example.com"}
            },
            wantErr:   false,
            wantEmail: "new@example.com",
        },
        {
            name:     "user not found",
            userID:   "999",
            newEmail: "new@example.com",
            setup:    func(m *MockUserRepo) {},
            wantErr:  true,
        },
        {
            name:     "save fails",
            userID:   "1",
            newEmail: "new@example.com",
            setup: func(m *MockUserRepo) {
                m.Users["1"] = &User{ID: "1", Name: "Test", Email: "old@example.com"}
                m.SaveErr = errors.New("db error")
            },
            wantErr: true,
        },
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            mock := &MockUserRepo{Users: make(map[string]*User)}
            tt.setup(mock)
            svc := NewUserService(mock)

            err := svc.UpdateEmail(context.Background(), tt.userID, tt.newEmail)

            if (err != nil) != tt.wantErr {
                t.Errorf("UpdateEmail() error = %v, wantErr %v", err, tt.wantErr)
            }
            if !tt.wantErr && mock.Users[tt.userID].Email != tt.wantEmail {
                t.Errorf("Email = %v, want %v", mock.Users[tt.userID].Email, tt.wantEmail)
            }
        })
    }
}

