        return PushNotifier{DeviceID: target}, nil
    default:
        return nil, errors.New("unknown notifier type: " + notifierType)
    }
}

func main() {
    // Client doesn't know about concrete types
    notifiers := []struct {
        kind   string
        target string
    }{
        {"email", "user@example.com"},
        {"sms", "+1234567890"},
        {"push", "device-abc-123"},
    }

    for _, n := range notifiers {
        notifier, err := NewNotifier(n.kind, n.target)
        if err != nil {
            fmt.Println("Error:", err)
            continue
        }
        notifier.Send("Server is down!")
    }
}

