import (
    "fmt"
    "strings"
    "time"
)

// The complex object we're building
type HTTPRequest struct {
    Method  string
    URL     string
    Headers map[string]string
    Body    string
    Timeout time.Duration
    Retries int
}

func (r HTTPRequest) String() string {
    var sb strings.Builder
    sb.WriteString(fmt.Sprintf("%s %s\n", r.Method, r.URL))
    for k, v := range r.Headers {
        sb.WriteString(fmt.Sprintf("  %s: %s\n", k, v))
    }
    if r.Body != "" {
        sb.WriteString(fmt.Sprintf("  Body: %s\n", r.Body))
    }
    sb.WriteString(fmt.Sprintf("  Timeout: %v, Retries: %d", r.Timeout, r.Retries))
    return sb.String()
}

// Builder with method chaining
type RequestBuilder struct {
    request HTTPRequest
}

func NewRequestBuilder(method, url string) *RequestBuilder {
    return &RequestBuilder{
        request: HTTPRequest{
            Method:  method,
            URL:     url,
            Headers: make(map[string]string),
            Timeout: 30 * time.Second,  // sensible default
            Retries: 3,                  // sensible default
        },
    }
}

func (b *RequestBuilder) Header(key, value string) *RequestBuilder {
    b.request.Headers[key] = value
    return b
}

func (b *RequestBuilder) Body(body string) *RequestBuilder {
    b.request.Body = body
    return b
}

func (b *RequestBuilder) Timeout(d time.Duration) *RequestBuilder {
    b.request.Timeout = d
    return b
}

func (b *RequestBuilder) Retries(n int) *RequestBuilder {
    b.request.Retries = n
    return b
}

func (b *RequestBuilder) Build() HTTPRequest {
    return b.request
}

func main() {
    // Simple request: just method and URL
    simple := NewRequestBuilder("GET", "https://api.example.com/users").
        Build()
    fmt.Println("Simple request:")
    fmt.Println(simple)

    fmt.Println()

    // Complex request: many options
    complex := NewRequestBuilder("POST", "https://api.example.com/orders").
        Header("Content-Type", "application/json").
        Header("Authorization", "Bearer token123").
        Body(`{"item": "widget", "qty": 5}`).
        Timeout(10 * time.Second).
        Retries(5).
        Build()
    fmt.Println("Complex request:")
    fmt.Println(complex)
}

