import (
    "fmt"
    "sync"
)

// Config is our singleton type
type Config struct {
    DatabaseURL string
    APIKey      string
    MaxConns    int
}

var (
    instance *Config
    once     sync.Once
)

// GetConfig returns the singleton instance
// Thread-safe: sync.Once guarantees init runs exactly once
func GetConfig() *Config {
    once.Do(func() {
        fmt.Println("Initializing config (this happens only once)")
        instance = &Config{
            DatabaseURL: "postgres://localhost:5432/mydb",
            APIKey:      "secret-api-key",
            MaxConns:    10,
        }
    })
    return instance
}

func main() {
    // Multiple calls, but initialization happens once
    var wg sync.WaitGroup
    for i := 0; i < 5; i++ {
        wg.Add(1)
        go func(id int) {
            defer wg.Done()
            cfg := GetConfig()
            fmt.Printf("Goroutine %d: MaxConns = %d\n", id, cfg.MaxConns)
        }(i)
    }
    wg.Wait()

    // Same instance everywhere
    cfg1 := GetConfig()
    cfg2 := GetConfig()
    fmt.Printf("Same instance? %v\n", cfg1 == cfg2)
}

