import "fmt"

// Base interface
type Handler interface {
    Handle(request string) string
}

// Concrete handler
type BaseHandler struct{}

func (h BaseHandler) Handle(request string) string {
    return fmt.Sprintf("Processed: %s", request)
}

// Logging decorator
type LoggingDecorator struct {
    wrapped Handler
}

func WithLogging(h Handler) Handler {
    return &LoggingDecorator{wrapped: h}
}

func (d *LoggingDecorator) Handle(request string) string {
    fmt.Printf("LOG: Incoming request: %s\n", request)
    result := d.wrapped.Handle(request)
    fmt.Printf("LOG: Response: %s\n", result)
    return result
}

// Auth decorator
type AuthDecorator struct {
    wrapped Handler
}

func WithAuth(h Handler) Handler {
    return &AuthDecorator{wrapped: h}
}

func (d *AuthDecorator) Handle(request string) string {
    fmt.Println("AUTH: Checking credentials...")
    // In real code, you'd validate tokens here
    return d.wrapped.Handle(request)
}

// Rate limiting decorator
type RateLimitDecorator struct {
    wrapped Handler
    limit   int
    count   int
}

func WithRateLimit(h Handler, limit int) Handler {
    return &RateLimitDecorator{wrapped: h, limit: limit}
}

func (d *RateLimitDecorator) Handle(request string) string {
    d.count++
    if d.count > d.limit {
        return "ERROR: Rate limit exceeded"
    }
    fmt.Printf("RATE: Request %d of %d\n", d.count, d.limit)
    return d.wrapped.Handle(request)
}

func main() {
    // Stack decorators: rate limit -> auth -> logging -> base
    handler := WithRateLimit(
        WithAuth(
            WithLogging(
                BaseHandler{},
            ),
        ),
        2, // max 2 requests
    )

    fmt.Println("=== Request 1 ===")
    fmt.Println("Result:", handler.Handle("GET /users"))

    fmt.Println("\n=== Request 2 ===")
    fmt.Println("Result:", handler.Handle("GET /orders"))

    fmt.Println("\n=== Request 3 ===")
    fmt.Println("Result:", handler.Handle("GET /products"))
}

