}

type VideoDecoder struct{}

func (d *VideoDecoder) Decode(data []byte) []byte {
    fmt.Println("  Decoding video frames...")
    return []byte("decoded frames")
}

type VideoEncoder struct{}

func (e *VideoEncoder) Encode(frames []byte, format string) []byte {
    fmt.Printf("  Encoding to %s format...\n", format)
    return []byte("encoded video")
}

