import (
    "fmt"
    "time"
)

// Image interface
type Image interface {
    Display() string
}

// Real image: expensive to create (simulates loading from disk)
type RealImage struct {
    filename string
    data     string
}

func NewRealImage(filename string) *RealImage {
    img := &RealImage{filename: filename}
    img.loadFromDisk()
    return img
}

func (i *RealImage) loadFromDisk() {
    fmt.Printf("Loading %s from disk...\n", i.filename)
    time.Sleep(100 * time.Millisecond)  // Simulate slow load
    i.data = fmt.Sprintf("[Image data for %s]", i.filename)
}

func (i *RealImage) Display() string {
    return i.data
}

// Proxy: lazy-loads the real image only when needed
type ImageProxy struct {
    filename string
    real     *RealImage
}

func NewImageProxy(filename string) *ImageProxy {
    fmt.Printf("Created proxy for %s (not loaded yet)\n", filename)
    return &ImageProxy{filename: filename}
}

func (p *ImageProxy) Display() string {
    // Lazy initialization: load only when first accessed
    if p.real == nil {
        p.real = NewRealImage(p.filename)
    }
    return p.real.Display()
}

func main() {
    // Create proxies (fast, no disk I/O)
    images := []Image{
        NewImageProxy("photo1.jpg"),
        NewImageProxy("photo2.jpg"),
        NewImageProxy("photo3.jpg"),
    }
    fmt.Println()

    // Only display first image (only it gets loaded)
    fmt.Println("Displaying first image:")
    fmt.Println(images[0].Display())
    fmt.Println()

    // Display first again (already loaded, instant)
    fmt.Println("Displaying first image again:")
    fmt.Println(images[0].Display())
}

