import (
    "strings"
    "testing"
)

// Interface for decorator testing
type DataProcessor interface {
    Process(data string) string
}

// Base implementation
type SimpleProcessor struct{}

func (s SimpleProcessor) Process(data string) string {
    return strings.ToUpper(data)
}

// Decorator: adds prefix and suffix
type LoggingDecorator struct {
    Wrapped DataProcessor
    Prefix  string
}

func (l LoggingDecorator) Process(data string) string {
    result := l.Wrapped.Process(data)
    return l.Prefix + ": " + result
}

// Decorator: validates input
type ValidatingDecorator struct {
    Wrapped  DataProcessor
    MinLen   int
    Fallback string
}

func (v ValidatingDecorator) Process(data string) string {
    if len(data) < v.MinLen {
        return v.Fallback
    }
    return v.Wrapped.Process(data)
}

// Mock for testing decorators in isolation
type MockProcessor struct {
    Calls  []string
    Return string
}

func (m *MockProcessor) Process(data string) string {
    m.Calls = append(m.Calls, data)
    return m.Return
}

func TestLoggingDecorator(t *testing.T) {
    mock := &MockProcessor{Return: "RESULT"}
    decorator := LoggingDecorator{Wrapped: mock, Prefix: "LOG"}

    result := decorator.Process("input")

    if len(mock.Calls) != 1 || mock.Calls[0] != "input" {
        t.Error("decorator should delegate to wrapped")
    }
    if result != "LOG: RESULT" {
        t.Errorf("result = %s, want LOG: RESULT", result)
    }
}

func TestValidatingDecorator(t *testing.T) {
    tests := []struct {
        name     string
        input    string
        minLen   int
        fallback string
        want     string
        wantCall bool
    }{
        {"valid input", "hello", 3, "invalid", "PROCESSED", true},
        {"input too short", "hi", 3, "too short", "too short", false},
        {"exact length", "abc", 3, "invalid", "PROCESSED", true},
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            mock := &MockProcessor{Return: "PROCESSED"}
            decorator := ValidatingDecorator{
                Wrapped:  mock,
                MinLen:   tt.minLen,
                Fallback: tt.fallback,
            }

            result := decorator.Process(tt.input)

            if result != tt.want {
                t.Errorf("result = %s, want %s", result, tt.want)
            }
            if tt.wantCall && len(mock.Calls) == 0 {
                t.Error("expected delegation to wrapped")
            }
            if !tt.wantCall && len(mock.Calls) > 0 {
                t.Error("should not delegate when validation fails")
            }
        })
    }
}

func TestDecoratorChaining(t *testing.T) {
    base := SimpleProcessor{}
    validated := ValidatingDecorator{Wrapped: base, MinLen: 2, Fallback: "ERR"}
    logged := LoggingDecorator{Wrapped: validated, Prefix: "OUT"}

    // Valid input goes through all decorators
    result := logged.Process("test")
    if result != "OUT: TEST" {
        t.Errorf("chained result = %s, want OUT: TEST", result)
    }

    // Invalid input stops at validator
    result = logged.Process("x")
    if result != "OUT: ERR" {
        t.Errorf("invalid result = %s, want OUT: ERR", result)
    }
}

