import "fmt"

// Strategy interface
type PaymentStrategy interface {
    Pay(amount float64) string
}

// Concrete strategies
type CreditCardStrategy struct {
    CardNumber string
}

func (c CreditCardStrategy) Pay(amount float64) string {
    return fmt.Sprintf("Paid $%.2f with credit card ending in %s",
        amount, c.CardNumber[len(c.CardNumber)-4:])
}

type PayPalStrategy struct {
    Email string
}

func (p PayPalStrategy) Pay(amount float64) string {
    return fmt.Sprintf("Paid $%.2f via PayPal (%s)", amount, p.Email)
}

type CryptoStrategy struct {
    WalletAddress string
}

func (c CryptoStrategy) Pay(amount float64) string {
    return fmt.Sprintf("Paid $%.2f in crypto to %s", amount, c.WalletAddress[:8]+"...")
}

// Context that uses strategies
type ShoppingCart struct {
    items   []string
    total   float64
    payment PaymentStrategy
}

func NewShoppingCart() *ShoppingCart {
    return &ShoppingCart{}
}

func (c *ShoppingCart) AddItem(name string, price float64) {
