package main

import (
    "fmt"
    "sort"
)

// Strategy as a function type
type SortStrategy func([]int)

// Built-in strategies
func AscendingSort(data []int) {
    sort.Ints(data)
}

func DescendingSort(data []int) {
    sort.Sort(sort.Reverse(sort.IntSlice(data)))
}

func AbsoluteSort(data []int) {
    sort.Slice(data, func(i, j int) bool {
        ai, aj := data[i], data[j]
        if ai < 0 { ai = -ai }
        if aj < 0 { aj = -aj }
        return ai < aj
    })
}

// Context using function strategy
type DataProcessor struct {
    data []int
    sort SortStrategy
}

func (p *DataProcessor) SetStrategy(s SortStrategy) {
    p.sort = s
}

func (p *DataProcessor) Process() {
    if p.sort != nil {
        p.sort(p.data)
    }
}

func main() {
    processor := &DataProcessor{data: []int{-5, 2, -8, 1, 9, -3}}
    fmt.Println("Original:", processor.data)

    processor.SetStrategy(AscendingSort)
    processor.Process()
    fmt.Println("Ascending:", processor.data)

    processor.data = []int{-5, 2, -8, 1, 9, -3}  // Reset
    processor.SetStrategy(DescendingSort)
    processor.Process()
    fmt.Println("Descending:", processor.data)

    processor.data = []int{-5, 2, -8, 1, 9, -3}  // Reset
    processor.SetStrategy(AbsoluteSort)
    processor.Process()
    fmt.Println("By absolute:", processor.data)

    // Inline strategy
    processor.data = []int{-5, 2, -8, 1, 9, -3}  // Reset
    processor.SetStrategy(func(data []int) {
        // Custom: sort odds before evens
        sort.Slice(data, func(i, j int) bool {
            iOdd, jOdd := data[i]%2 != 0, data[j]%2 != 0
            if iOdd != jOdd {
                return iOdd  // Odds first
            }
            return data[i] < data[j]
        })
    })
    processor.Process()
    fmt.Println("Odds first:", processor.data)
}

