import "fmt"

// Observer interface
type PriceObserver interface {
    OnPriceChange(symbol string, price float64)
}

// Subject (Observable)
type StockTicker struct {
    observers []PriceObserver
    prices    map[string]float64
}

func NewStockTicker() *StockTicker {
    return &StockTicker{
        prices: make(map[string]float64),
    }
}

func (s *StockTicker) Subscribe(observer PriceObserver) {
    s.observers = append(s.observers, observer)
}

func (s *StockTicker) UpdatePrice(symbol string, price float64) {
    s.prices[symbol] = price
    s.notifyAll(symbol, price)
}

func (s *StockTicker) notifyAll(symbol string, price float64) {
    for _, observer := range s.observers {
        observer.OnPriceChange(symbol, price)
    }
}

// Concrete observers
type PriceDisplay struct {
    name string
}

func (d PriceDisplay) OnPriceChange(symbol string, price float64) {
    fmt.Printf("[%s] %s: $%.2f\n", d.name, symbol, price)
}

type PriceAlert struct {
    threshold float64
}

func (a PriceAlert) OnPriceChange(symbol string, price float64) {
    if price > a.threshold {
        fmt.Printf("ALERT: %s exceeded $%.2f (now $%.2f)\n",
            symbol, a.threshold, price)
    }
}

type PriceLogger struct{}

func (l PriceLogger) OnPriceChange(symbol string, price float64) {
    fmt.Printf("LOG: Price update - %s = %.2f\n", symbol, price)
}

func main() {
    ticker := NewStockTicker()

    // Subscribe different observers
    ticker.Subscribe(PriceDisplay{name: "Main Screen"})
    ticker.Subscribe(PriceAlert{threshold: 150.00})
    ticker.Subscribe(PriceLogger{})

    fmt.Println("=== AAPL Update ===")
    ticker.UpdatePrice("AAPL", 145.50)

    fmt.Println("\n=== AAPL Update ===")
    ticker.UpdatePrice("AAPL", 152.30)  // Triggers alert

    fmt.Println("\n=== GOOG Update ===")
    ticker.UpdatePrice("GOOG", 140.00)
}

