// Receiver: the text editor state
type Document struct {
    content strings.Builder
}

func (d *Document) Insert(text string) {
    d.content.WriteString(text)
}

func (d *Document) Delete(n int) string {
    s := d.content.String()
    if n > len(s) {
        n = len(s)
    }
    deleted := s[len(s)-n:]
    d.content.Reset()
    d.content.WriteString(s[:len(s)-n])
    return deleted
}

func (d *Document) String() string {
    return d.content.String()
}

// Concrete commands
type InsertCommand struct {
    doc  *Document
    text string
}

func (c *InsertCommand) Execute() {
    c.doc.Insert(c.text)
}

func (c *InsertCommand) Undo() {
    c.doc.Delete(len(c.text))
}

func (c *InsertCommand) Description() string {
    return fmt.Sprintf("Insert '%s'", c.text)
}

type DeleteCommand struct {
    doc     *Document
    count   int
    deleted string  // For undo
}

func (c *DeleteCommand) Execute() {
    c.deleted = c.doc.Delete(c.count)
}

func (c *DeleteCommand) Undo() {
    c.doc.Insert(c.deleted)
}

func (c *DeleteCommand) Description() string {
    return fmt.Sprintf("Delete %d chars", c.count)
}

// Invoker: manages command execution and history
type Editor struct {
    doc     *Document
    history []Command
    undone  []Command
}

func NewEditor() *Editor {
    return &Editor{doc: &Document{}}
}

func (e *Editor) Execute(cmd Command) {
    cmd.Execute()
    e.history = append(e.history, cmd)
    e.undone = nil  // Clear redo stack
    fmt.Printf("Executed: %s\n", cmd.Description())
}

func (e *Editor) Undo() {
    if len(e.history) == 0 {
        fmt.Println("Nothing to undo")
        return
    }
    cmd := e.history[len(e.history)-1]
    e.history = e.history[:len(e.history)-1]
    cmd.Undo()
    e.undone = append(e.undone, cmd)
    fmt.Printf("Undone: %s\n", cmd.Description())
}

func (e *Editor) Redo() {
    if len(e.undone) == 0 {
        fmt.Println("Nothing to redo")
        return
    }
    cmd := e.undone[len(e.undone)-1]
    e.undone = e.undone[:len(e.undone)-1]
    cmd.Execute()
    e.history = append(e.history, cmd)
    fmt.Printf("Redone: %s\n", cmd.Description())
}

func (e *Editor) Content() string {
    return e.doc.String()
}

func main() {
    editor := NewEditor()

    editor.Execute(&InsertCommand{doc: editor.doc, text: "Hello"})
    fmt.Printf("Content: '%s'\n\n", editor.Content())

    editor.Execute(&InsertCommand{doc: editor.doc, text: " World"})
    fmt.Printf("Content: '%s'\n\n", editor.Content())

    editor.Execute(&DeleteCommand{doc: editor.doc, count: 6})
    fmt.Printf("Content: '%s'\n\n", editor.Content())

    fmt.Println("--- Undo twice ---")
    editor.Undo()
    fmt.Printf("Content: '%s'\n", editor.Content())
    editor.Undo()
    fmt.Printf("Content: '%s'\n\n", editor.Content())

    fmt.Println("--- Redo ---")
    editor.Redo()
    fmt.Printf("Content: '%s'\n", editor.Content())
}

