package main

import (
    "errors"
    "testing"
)

// Strategy interface
type PaymentStrategy interface {
    Pay(amount float64) (string, error)
}

// MockPayment records calls and returns configured results
type MockPayment struct {
    Calls     []float64
    ReturnMsg string
    ReturnErr error
}

func (m *MockPayment) Pay(amount float64) (string, error) {
    m.Calls = append(m.Calls, amount)
    return m.ReturnMsg, m.ReturnErr
}

// Service using strategy
type Checkout struct {
    payment PaymentStrategy
}

func (c *Checkout) Process(items []float64) (string, error) {
    var total float64
    for _, item := range items {
        total += item
    }
    return c.payment.Pay(total)
}

func TestCheckout_CalculatesTotal(t *testing.T) {
    tests := []struct {
        name      string
        items     []float64
        wantTotal float64
    }{
        {"single item", []float64{10.0}, 10.0},
        {"multiple items", []float64{10.0, 20.0, 30.0}, 60.0},
        {"empty cart", []float64{}, 0.0},
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            mock := &MockPayment{ReturnMsg: "ok"}
            checkout := &Checkout{payment: mock}

            checkout.Process(tt.items)

            if len(mock.Calls) != 1 {
                t.Fatalf("Expected 1 call, got %d", len(mock.Calls))
            }
            if mock.Calls[0] != tt.wantTotal {
                t.Errorf("Pay called with %v, want %v", mock.Calls[0], tt.wantTotal)
            }
        })
    }
}

func TestCheckout_PropagatesError(t *testing.T) {
    mock := &MockPayment{ReturnErr: errors.New("payment failed")}
    checkout := &Checkout{payment: mock}

    _, err := checkout.Process([]float64{100.0})

    if err == nil {
        t.Error("Expected error to be propagated")
    }
}

func TestCheckout_ReturnsMessage(t *testing.T) {
    mock := &MockPayment{ReturnMsg: "Payment ID: 12345"}
    checkout := &Checkout{payment: mock}

    msg, err := checkout.Process([]float64{50.0})

    if err != nil {
        t.Fatalf("Unexpected error: %v", err)
    }
    if msg != "Payment ID: 12345" {
        t.Errorf("Got %q, want %q", msg, "Payment ID: 12345")
    }
}

