// Small, focused interfaces

// Getter is the minimal interface for reading
type Getter interface {
    Get(key string) (any, bool)
}

// Setter is the minimal interface for writing
type Setter interface {
    Set(key string, value any)
}

// Deleter is the minimal interface for removing
type Deleter interface {
    Delete(key string)
}

