package main

import (
    "container/list"
    "fmt"
    "sync"
    "time"
)

// entry holds the cached data
type entry struct {
    key       string
    value     any
    expiresAt time.Time
}

func (e *entry) isExpired() bool {
    return !e.expiresAt.IsZero() && time.Now().After(e.expiresAt)
}

// LRUCache implements an LRU cache with TTL support
type LRUCache struct {
    capacity int
    items    map[string]*list.Element
    order    *list.List  // Front = MRU, Back = LRU
    mu       sync.RWMutex
    defaultTTL time.Duration
}

// NewLRUCache creates a cache with the given capacity
func NewLRUCache(capacity int, defaultTTL time.Duration) *LRUCache {
    return &LRUCache{
        capacity:   capacity,
        items:      make(map[string]*list.Element),
        order:      list.New(),
        defaultTTL: defaultTTL,
    }
}

// Get retrieves a value and moves it to front (most recently used)
func (c *LRUCache) Get(key string) (any, bool) {
    c.mu.Lock()
    defer c.mu.Unlock()

    elem, exists := c.items[key]
    if !exists {
        return nil, false
    }

    e := elem.Value.(*entry)
    if e.isExpired() {
        c.removeElement(elem)
        return nil, false
    }

    c.order.MoveToFront(elem)
    return e.value, true
}

// Set stores a value, evicting LRU item if at capacity
func (c *LRUCache) Set(key string, value any) {
    c.SetWithTTL(key, value, c.defaultTTL)
}

// SetWithTTL stores a value with a specific TTL
func (c *LRUCache) SetWithTTL(key string, value any, ttl time.Duration) {
    c.mu.Lock()
    defer c.mu.Unlock()

    var expiresAt time.Time
    if ttl > 0 {
        expiresAt = time.Now().Add(ttl)
    }

    // Update existing
    if elem, exists := c.items[key]; exists {
        c.order.MoveToFront(elem)
        e := elem.Value.(*entry)
        e.value = value
        e.expiresAt = expiresAt
        return
    }

    // Evict if at capacity
    for c.order.Len() >= c.capacity {
        c.evictOldest()
    }

    // Insert new
    e := &entry{key: key, value: value, expiresAt: expiresAt}
    elem := c.order.PushFront(e)
    c.items[key] = elem
}

// Delete removes a key from the cache
func (c *LRUCache) Delete(key string) {
    c.mu.Lock()
    defer c.mu.Unlock()

    if elem, exists := c.items[key]; exists {
        c.removeElement(elem)
    }
}

// Len returns the number of items in the cache
func (c *LRUCache) Len() int {
    c.mu.RLock()
    defer c.mu.RUnlock()
    return c.order.Len()
}

func (c *LRUCache) evictOldest() {
    elem := c.order.Back()
    if elem != nil {
        c.removeElement(elem)
    }
}

func (c *LRUCache) removeElement(elem *list.Element) {
    c.order.Remove(elem)
    e := elem.Value.(*entry)
    delete(c.items, e.key)
}

func main() {
    cache := NewLRUCache(3, 5*time.Second)

    // Add items
    cache.Set("a", 1)
    cache.Set("b", 2)
    cache.Set("c", 3)
    fmt.Printf("After adding a, b, c: size=%d\n", cache.Len())

    // Access 'a' (moves to front, becomes MRU)
    if val, ok := cache.Get("a"); ok {
        fmt.Printf("Got a=%v\n", val)
    }

    // Add 'd' - should evict 'b' (LRU)
    cache.Set("d", 4)
    fmt.Printf("After adding d: size=%d\n", cache.Len())

    // Check what's in cache
    for _, key := range []string{"a", "b", "c", "d"} {
        if val, ok := cache.Get(key); ok {
            fmt.Printf("  %s: %v\n", key, val)
        } else {
            fmt.Printf("  %s: not found (evicted)\n", key)
        }
    }

    // TTL demo
    fmt.Println("\nTTL demonstration:")
    cache.SetWithTTL("temp", "expires soon", 100*time.Millisecond)
    if val, ok := cache.Get("temp"); ok {
        fmt.Printf("Before expiry: temp=%v\n", val)
    }
    time.Sleep(150 * time.Millisecond)
    if _, ok := cache.Get("temp"); !ok {
        fmt.Println("After expiry: temp not found")
    }
}

