func TestLRUCache_BasicOperations(t *testing.T) {
    tests := []struct {
        name     string
        ops      func(*LRUCache)
        checkKey string
        wantVal  any
        wantOk   bool
    }{
        {
            name: "set and get",
            ops: func(c *LRUCache) {
                c.Set("key1", "value1")
            },
            checkKey: "key1",
            wantVal:  "value1",
            wantOk:   true,
        },
        {
            name: "get non-existent key",
            ops: func(c *LRUCache) {
                c.Set("key1", "value1")
            },
            checkKey: "key2",
            wantVal:  nil,
            wantOk:   false,
        },
        {
            name: "overwrite existing key",
            ops: func(c *LRUCache) {
                c.Set("key1", "value1")
                c.Set("key1", "value2")
            },
            checkKey: "key1",
            wantVal:  "value2",
            wantOk:   true,
        },
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            cache := NewLRUCache(10, 0)
            tt.ops(cache)
            got, ok := cache.Get(tt.checkKey)
            if ok != tt.wantOk {
                t.Errorf("Get() ok = %v, want %v", ok, tt.wantOk)
            }
            if got != tt.wantVal {
                t.Errorf("Get() = %v, want %v", got, tt.wantVal)
            }
        })
    }
}

func TestLRUCache_Eviction(t *testing.T) {
    cache := NewLRUCache(3, 0)

    cache.Set("a", 1)
    cache.Set("b", 2)
    cache.Set("c", 3)

    // Access 'a' to make it recently used
    cache.Get("a")

    // Add 'd', should evict 'b' (least recently used)
    cache.Set("d", 4)

    if _, ok := cache.Get("b"); ok {
        t.Error("Expected 'b' to be evicted")
    }
    if _, ok := cache.Get("a"); !ok {
        t.Error("Expected 'a' to still exist")
    }
    if cache.Len() != 3 {
        t.Errorf("Expected len=3, got %d", cache.Len())
    }
}

func TestLRUCache_TTLExpiry(t *testing.T) {
    cache := NewLRUCache(10, 50*time.Millisecond)

    cache.Set("temp", "value")

    // Should exist immediately
    if _, ok := cache.Get("temp"); !ok {
        t.Error("Expected key to exist before TTL")
    }

    // Wait for expiry
    time.Sleep(60 * time.Millisecond)

    // Should be expired
    if _, ok := cache.Get("temp"); ok {
        t.Error("Expected key to be expired")
    }
}

package main

import (
    "fmt"
    "sync"
    "time"
)

// TokenBucket implements the token bucket algorithm.
// Tokens accumulate at refillRate per second up to capacity.
// Each Allow() call consumes one token.
type TokenBucket struct {
    capacity   float64
    tokens     float64
    refillRate float64
    lastRefill time.Time
    mu         sync.Mutex
}

// NewTokenBucket creates a bucket with given capacity and refill rate
func NewTokenBucket(capacity float64, refillRate float64) *TokenBucket {
    return &TokenBucket{
        capacity:   capacity,
        tokens:     capacity, // Start full
        refillRate: refillRate,
        lastRefill: time.Now(),
    }
}

// Allow checks if a request is allowed (consumes one token)
func (b *TokenBucket) Allow() bool {
    b.mu.Lock()
    defer b.mu.Unlock()

    b.refill()

    if b.tokens >= 1 {
        b.tokens--
        return true
    }
    return false
}

// refill adds tokens based on elapsed time since last refill
func (b *TokenBucket) refill() {
    now := time.Now()
    elapsed := now.Sub(b.lastRefill).Seconds()
    b.tokens += elapsed * b.refillRate
    if b.tokens > b.capacity {
        b.tokens = b.capacity
    }
    b.lastRefill = now
}

// RateLimiter manages per-key rate limiting
type RateLimiter struct {
    buckets    map[string]*TokenBucket
    capacity   float64
    refillRate float64
    mu         sync.Mutex
}

// NewRateLimiter creates a limiter with given settings
func NewRateLimiter(capacity, refillRate float64) *RateLimiter {
    return &RateLimiter{
        buckets:    make(map[string]*TokenBucket),
        capacity:   capacity,
        refillRate: refillRate,
    }
}

// Allow checks if a request from the given key is allowed
func (r *RateLimiter) Allow(key string) bool {
    r.mu.Lock()
    bucket, exists := r.buckets[key]
    if !exists {
        bucket = NewTokenBucket(r.capacity, r.refillRate)
        r.buckets[key] = bucket
    }
    r.mu.Unlock()

    return bucket.Allow()
}

func main() {
    // 5 requests max, refills 2 per second
    limiter := NewRateLimiter(5, 2)

    // Burst of 7 requests
    fmt.Println("Burst test (capacity=5):")
    for i := 1; i <= 7; i++ {
        allowed := limiter.Allow("user1")
        fmt.Printf("  Request %d: %v\n", i, allowed)
    }

    // Wait for refill
    fmt.Println("\nWaiting 2 seconds for refill...")
    time.Sleep(2 * time.Second)

    // Should have ~4 tokens now (2 per second * 2 seconds)
    fmt.Println("After refill:")
    for i := 1; i <= 6; i++ {
        allowed := limiter.Allow("user1")
        fmt.Printf("  Request %d: %v\n", i, allowed)
    }

    // Different key has its own bucket
    fmt.Println("\nDifferent user (user2):")
    for i := 1; i <= 6; i++ {
        allowed := limiter.Allow("user2")
        fmt.Printf("  Request %d: %v\n", i, allowed)
    }
}

