import (
    "fmt"
    "sync"
    "time"
)

// SlidingWindowLimiter uses sliding window counter algorithm
type SlidingWindowLimiter struct {
    limit    int
    window   time.Duration
    counters map[string]*windowCounter
    mu       sync.Mutex
}

type windowCounter struct {
    prevCount   int
    currCount   int
    windowStart time.Time
}

// NewSlidingWindowLimiter creates a limiter
func NewSlidingWindowLimiter(limit int, window time.Duration) *SlidingWindowLimiter {
    return &SlidingWindowLimiter{
        limit:    limit,
        window:   window,
        counters: make(map[string]*windowCounter),
    }
}

// Allow checks if request is allowed using sliding window calculation
func (l *SlidingWindowLimiter) Allow(key string) bool {
    l.mu.Lock()
    defer l.mu.Unlock()

    now := time.Now()
    counter, exists := l.counters[key]
    if !exists {
        counter = &windowCounter{windowStart: now}
        l.counters[key] = counter
    }

    elapsed := now.Sub(counter.windowStart)

    // Move to new window if needed
    if elapsed >= l.window {
        windowsPassed := int(elapsed / l.window)
        if windowsPassed == 1 {
            counter.prevCount = counter.currCount
        } else {
            counter.prevCount = 0
        }
        counter.currCount = 0
        counter.windowStart = counter.windowStart.Add(
            time.Duration(windowsPassed) * l.window,
        )
        elapsed = now.Sub(counter.windowStart)
    }

    // Calculate weighted count: previous window weight + current count
    prevWeight := 1.0 - (float64(elapsed) / float64(l.window))
    weightedCount := float64(counter.prevCount)*prevWeight + float64(counter.currCount)

    if int(weightedCount) >= l.limit {
        return false
    }

    counter.currCount++
    return true
}

func main() {
    // 10 requests per second
    limiter := NewSlidingWindowLimiter(10, time.Second)

    fmt.Println("Sliding Window Rate Limiter (10 req/sec)")
    fmt.Println("\nFirst burst:")
    for i := 1; i <= 12; i++ {
        allowed := limiter.Allow("user1")
        fmt.Printf("  Request %2d: %v\n", i, allowed)
    }

    // Wait for window rollover + half of new window
    fmt.Println("\nWaiting 1.5s (full window + half)...")
    time.Sleep(1500 * time.Millisecond)

    // Previous window (10 requests) weighted by ~0.5 = ~5
    // So we can do ~5 more before hitting limit
    fmt.Println("After 1.5s (previous window weighted ~50%):")
    for i := 1; i <= 7; i++ {
        allowed := limiter.Allow("user1")
        fmt.Printf("  Request %2d: %v\n", i, allowed)
    }
}

