import (
    "sync"
    "testing"
    "time"
)

type TokenBucket struct {
    capacity   float64
    tokens     float64
    refillRate float64
    lastRefill time.Time
    mu         sync.Mutex
}

func NewTokenBucket(capacity float64, refillRate float64) *TokenBucket {
    return &TokenBucket{
        capacity:   capacity,
        tokens:     capacity,
        refillRate: refillRate,
        lastRefill: time.Now(),
    }
}

func (b *TokenBucket) Allow() bool {
    b.mu.Lock()
    defer b.mu.Unlock()
    b.refill()
    if b.tokens >= 1 {
        b.tokens--
        return true
    }
    return false
}

func (b *TokenBucket) refill() {
    now := time.Now()
    elapsed := now.Sub(b.lastRefill).Seconds()
    b.tokens += elapsed * b.refillRate
    if b.tokens > b.capacity {
        b.tokens = b.capacity
    }
    b.lastRefill = now
}

func TestTokenBucket_BurstLimit(t *testing.T) {
    bucket := NewTokenBucket(5, 1) // 5 burst, 1/sec refill

    // Should allow exactly 5 requests
    for i := 0; i < 5; i++ {
        if !bucket.Allow() {
            t.Errorf("Request %d should be allowed", i+1)
        }
    }

    // 6th request should be denied
    if bucket.Allow() {
        t.Error("Request 6 should be denied (over capacity)")
    }
}

func TestTokenBucket_Refill(t *testing.T) {
    bucket := NewTokenBucket(3, 10) // 3 burst, 10/sec refill

    // Exhaust all tokens
    for i := 0; i < 3; i++ {
        bucket.Allow()
    }

    if bucket.Allow() {
        t.Error("Should be empty after 3 requests")
    }

    // Wait for refill (100ms = 1 token at 10/sec)
    time.Sleep(150 * time.Millisecond)

    if !bucket.Allow() {
        t.Error("Should have refilled at least 1 token")
    }
}

func TestTokenBucket_Concurrent(t *testing.T) {
    bucket := NewTokenBucket(100, 0) // 100 tokens, no refill
    allowed := 0
    var mu sync.Mutex
    var wg sync.WaitGroup

    // 200 concurrent requests for 100 tokens
    for i := 0; i < 200; i++ {
        wg.Add(1)
        go func() {
            defer wg.Done()
            if bucket.Allow() {
                mu.Lock()
                allowed++
                mu.Unlock()
            }
        }()
    }
    wg.Wait()

    if allowed != 100 {
        t.Errorf("Expected exactly 100 allowed, got %d", allowed)
    }
}

package main

import (
    "errors"
    "fmt"
    "sort"
    "sync"
    "time"
)

// SpotSize represents the size of a parking spot
type SpotSize int

const (
    SpotSmall SpotSize = iota
    SpotMedium
    SpotLarge
)

func (s SpotSize) String() string {
    return []string{"Small", "Medium", "Large"}[s]
}

// VehicleType represents types of vehicles
type VehicleType int

const (
    Motorcycle VehicleType = iota
    Car
    Truck
)

func (v VehicleType) String() string {
    return []string{"Motorcycle", "Car", "Truck"}[v]
}

// MinSpotSize returns minimum spot size for vehicle type
func (v VehicleType) MinSpotSize() SpotSize {
    switch v {
    case Motorcycle:
        return SpotSmall
    case Car:
        return SpotMedium
    case Truck:
        return SpotLarge
    default:
        return SpotLarge
    }
}

// Vehicle represents a parked vehicle
type Vehicle struct {
    LicensePlate string
    Type         VehicleType
    EntryTime    time.Time
}

// Spot represents a parking spot
type Spot struct {
    ID      string
    Size    SpotSize
    Floor   int
    Vehicle *Vehicle
}

func (s *Spot) IsAvailable() bool {
    return s.Vehicle == nil
}

func (s *Spot) CanFit(v VehicleType) bool {
    return s.Size >= v.MinSpotSize()
}

// ParkingLot manages all floors and spots
type ParkingLot struct {
    name           string
    floors         int
    spots          [][]*Spot             // [floor][spot]
    vehicleToSpot  map[string]*Spot      // license -> spot
    availableSpots map[SpotSize][]*Spot  // size -> available spots
    hourlyRate     float64
    mu             sync.RWMutex
}

// NewParkingLot creates a parking lot with spots per floor
func NewParkingLot(name string, floors int, config map[SpotSize]int, hourlyRate float64) *ParkingLot {
    lot := &ParkingLot{
        name:           name,
        floors:         floors,
        hourlyRate:     hourlyRate,
        spots:          make([][]*Spot, floors),
        vehicleToSpot:  make(map[string]*Spot),
        availableSpots: make(map[SpotSize][]*Spot),
    }

    // Sort sizes for consistent spot creation order
    sizes := make([]SpotSize, 0, len(config))
    for size := range config {
        sizes = append(sizes, size)
    }
    sort.Slice(sizes, func(i, j int) bool { return sizes[i] < sizes[j] })

    spotID := 1
    for floor := 0; floor < floors; floor++ {
        for _, size := range sizes {
            count := config[size]
            for i := 0; i < count; i++ {
                spot := &Spot{
                    ID:    fmt.Sprintf("F%d-S%d", floor+1, spotID),
                    Size:  size,
                    Floor: floor,
                }
                lot.spots[floor] = append(lot.spots[floor], spot)
                lot.availableSpots[size] = append(lot.availableSpots[size], spot)
                spotID++
            }
        }
    }

    return lot
}

// Park attempts to park a vehicle in the smallest fitting spot
func (p *ParkingLot) Park(licensePlate string, vehicleType VehicleType) (*Spot, error) {
    p.mu.Lock()
    defer p.mu.Unlock()

    if _, exists := p.vehicleToSpot[licensePlate]; exists {
        return nil, errors.New("vehicle already parked")
    }

    // Find smallest fitting spot (iterate Small -> Medium -> Large)
    minSize := vehicleType.MinSpotSize()
    var spot *Spot
    for size := minSize; size <= SpotLarge; size++ {
        if avail := p.availableSpots[size]; len(avail) > 0 {
            spot = avail[len(avail)-1]
            p.availableSpots[size] = avail[:len(avail)-1]
            break
        }
    }

    if spot == nil {
        return nil, errors.New("no available spot")
    }

    vehicle := &Vehicle{
        LicensePlate: licensePlate,
        Type:         vehicleType,
        EntryTime:    time.Now(),
    }
    spot.Vehicle = vehicle
    p.vehicleToSpot[licensePlate] = spot

    return spot, nil
}

// Leave removes a vehicle and returns the fee
func (p *ParkingLot) Leave(licensePlate string) (float64, error) {
    p.mu.Lock()
    defer p.mu.Unlock()

    spot, exists := p.vehicleToSpot[licensePlate]
    if !exists {
        return 0, errors.New("vehicle not found")
    }

    duration := time.Since(spot.Vehicle.EntryTime)
    hours := duration.Hours()
    if hours < 1 {
        hours = 1 // Minimum 1 hour charge
    }
    fee := hours * p.hourlyRate

    // Return spot to available pool
    p.availableSpots[spot.Size] = append(p.availableSpots[spot.Size], spot)
    spot.Vehicle = nil
    delete(p.vehicleToSpot, licensePlate)

    return fee, nil
}

// AvailableSpots returns count of available spots per size
func (p *ParkingLot) AvailableSpots() map[SpotSize]int {
    p.mu.RLock()
    defer p.mu.RUnlock()

    result := make(map[SpotSize]int)
    for size, spots := range p.availableSpots {
        result[size] = len(spots)
    }
    return result
}

// AvailableSpotsString returns formatted available spots
func (p *ParkingLot) AvailableSpotsString() string {
    avail := p.AvailableSpots()
    return fmt.Sprintf("Small:%d, Medium:%d, Large:%d",
        avail[SpotSmall], avail[SpotMedium], avail[SpotLarge])
}

func main() {
    // Create lot: 2 floors, 2 small + 3 medium + 1 large per floor
    lot := NewParkingLot("Downtown Parking", 2, map[SpotSize]int{
        SpotSmall:  2,
        SpotMedium: 3,
        SpotLarge:  1,
    }, 5.0) // $5/hour

    fmt.Println("=== Parking Lot Simulation ===")
    fmt.Printf("Available: %s\n\n", lot.AvailableSpotsString())

    // Park various vehicles
    vehicles := []struct {
        plate string
        vType VehicleType
    }{
        {"MOTO-1", Motorcycle},
        {"CAR-1", Car},
        {"CAR-2", Car},
        {"TRUCK-1", Truck},
        {"TRUCK-2", Truck},
    }

    fmt.Println("Parking vehicles:")
    for _, v := range vehicles {
        spot, err := lot.Park(v.plate, v.vType)
        if err != nil {
            fmt.Printf("  %s (%s): %v\n", v.plate, v.vType, err)
        } else {
            fmt.Printf("  %s (%s): parked in %s (%s)\n",
                v.plate, v.vType, spot.ID, spot.Size)
        }
    }

    fmt.Printf("\nAvailable after parking: %s\n", lot.AvailableSpotsString())

    // Vehicle leaves
    fmt.Println("\nVehicle leaving:")
    fee, _ := lot.Leave("CAR-1")
    fmt.Printf("  CAR-1 left, fee: $%.2f\n", fee)

    fmt.Printf("\nAvailable after CAR-1 leaves: %s\n", lot.AvailableSpotsString())

    // Try to park third truck (should fail)
    fmt.Println("\nTrying to park third truck:")
    _, err := lot.Park("TRUCK-3", Truck)
    if err != nil {
        fmt.Printf("  TRUCK-3: %v\n", err)
    }
}

