                vType     VehicleType
                wantError bool
            }{
                {"MOTO-1", Motorcycle, false},
                {"MOTO-2", Motorcycle, true}, // No more spots
            },
        },
        {
            name:   "duplicate license plate",
            config: map[SpotSize]int{SpotMedium: 2},
            vehicles: []struct {
                plate     string
                vType     VehicleType
                wantError bool
            }{
                {"CAR-1", Car, false},
                {"CAR-1", Car, true}, // Already parked
            },
        },
        {
            name:   "car uses large spot when medium full",
            config: map[SpotSize]int{SpotSmall: 1, SpotLarge: 1},
            vehicles: []struct {
                plate     string
                vType     VehicleType
                wantError bool
            }{
                {"CAR-1", Car, false}, // Gets large spot
            },
        },
    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
