            for _, v := range tt.vehicles {
                _, err := lot.Park(v.plate, v.vType)
                if (err != nil) != v.wantError {
                    t.Errorf("Park(%s, %s) error = %v, wantError %v",
                        v.plate, v.vType, err, v.wantError)
                }
            }
        })
    }
}

func TestParkingLot_Leave(t *testing.T) {
    lot := NewParkingLot("Test", 1, map[SpotSize]int{SpotMedium: 2}, 10.0)

    // Park a car
    lot.Park("CAR-1", Car)

    // Leave returns fee (minimum 1 hour)
    fee, err := lot.Leave("CAR-1")
    if err != nil {
        t.Errorf("Leave(CAR-1) unexpected error: %v", err)
    }
    if fee < 10.0 {
        t.Errorf("Leave(CAR-1) fee = %v, want >= 10.0", fee)
    }

    // Leaving again should fail
    _, err = lot.Leave("CAR-1")
    if err == nil {
        t.Error("Leave(CAR-1) second time should fail")
    }

    // Leaving unknown vehicle should fail
    _, err = lot.Leave("UNKNOWN")
    if err == nil {
        t.Error("Leave(UNKNOWN) should fail")
    }
}

func TestParkingLot_AvailableSpots(t *testing.T) {
    config := map[SpotSize]int{SpotSmall: 2, SpotMedium: 3, SpotLarge: 1}
    lot := NewParkingLot("Test", 1, config, 5.0)

    // Initially all spots available
    avail := lot.AvailableSpots()
    for size, count := range config {
        if avail[size] != count {
            t.Errorf("Initial %s spots = %d, want %d", size, avail[size], count)
        }
    }

    // Park reduces available
    lot.Park("CAR-1", Car)
    avail = lot.AvailableSpots()
    if avail[SpotMedium] != 2 {
        t.Errorf("After parking car, Medium spots = %d, want 2", avail[SpotMedium])
    }

    // Leave restores available
    lot.Leave("CAR-1")
    avail = lot.AvailableSpots()
    if avail[SpotMedium] != 3 {
        t.Errorf("After leave, Medium spots = %d, want 3", avail[SpotMedium])
    }
}

package main

import (
    "encoding/json"
    "fmt"
    "io"
    "os"
    "strings"
    "sync"
    "time"
)

// Level represents log severity
type Level int

const (
    LevelDebug Level = iota
    LevelInfo
    LevelWarn
    LevelError
)

func (l Level) String() string {
    return []string{"DEBUG", "INFO", "WARN", "ERROR"}[l]
}

// Entry represents a log entry
type Entry struct {
    Level     Level
    Message   string
    Fields    map[string]any
    Timestamp time.Time
}

// Handler interface for different output strategies
type Handler interface {
    Handle(entry Entry) error
}

// ConsoleHandler writes to stdout
type ConsoleHandler struct {
    Writer io.Writer
    mu     sync.Mutex
}

func NewConsoleHandler() *ConsoleHandler {
    return &ConsoleHandler{Writer: os.Stdout}
}

func (h *ConsoleHandler) Handle(entry Entry) error {
    h.mu.Lock()
    defer h.mu.Unlock()

    var fields string
    if len(entry.Fields) > 0 {
        pairs := make([]string, 0, len(entry.Fields))
        for k, v := range entry.Fields {
            pairs = append(pairs, fmt.Sprintf("%s=%v", k, v))
        }
        fields = " " + strings.Join(pairs, " ")
    }

    fmt.Fprintf(h.Writer, "%s [%s] %s%s\n",
        entry.Timestamp.Format("15:04:05"),
        entry.Level,
        entry.Message,
        fields,
    )
    return nil
}

// JSONHandler writes JSON formatted logs
type JSONHandler struct {
    Writer io.Writer
    mu     sync.Mutex
}

func NewJSONHandler(w io.Writer) *JSONHandler {
    return &JSONHandler{Writer: w}
}

func (h *JSONHandler) Handle(entry Entry) error {
    h.mu.Lock()
    defer h.mu.Unlock()

    data := map[string]any{
        "time":    entry.Timestamp.Format(time.RFC3339),
        "level":   entry.Level.String(),
        "message": entry.Message,
    }
    for k, v := range entry.Fields {
        data[k] = v
    }

    bytes, err := json.Marshal(data)
    if err != nil {
        return err
    }
    fmt.Fprintln(h.Writer, string(bytes))
    return nil
}

// Logger is the main logging type
type Logger struct {
    handlers  []Handler
    minLevel  Level
    fields    map[string]any
    mu        sync.RWMutex
}

// New creates a new logger
func New() *Logger {
    return &Logger{
        handlers: []Handler{},
        minLevel: LevelInfo,
        fields:   make(map[string]any),
    }
}

// AddHandler adds an output handler
func (l *Logger) AddHandler(h Handler) *Logger {
    l.mu.Lock()
    defer l.mu.Unlock()
    l.handlers = append(l.handlers, h)
    return l
}

// SetLevel sets minimum log level
func (l *Logger) SetLevel(level Level) *Logger {
    l.mu.Lock()
    defer l.mu.Unlock()
    l.minLevel = level
    return l
}

// With returns a new logger with additional fields
func (l *Logger) With(key string, value any) *Logger {
    l.mu.RLock()
    newFields := make(map[string]any, len(l.fields)+1)
    for k, v := range l.fields {
        newFields[k] = v
    }
    l.mu.RUnlock()
    newFields[key] = value

    return &Logger{
        handlers: l.handlers,
        minLevel: l.minLevel,
        fields:   newFields,
    }
}

func (l *Logger) log(level Level, msg string, args ...any) {
    l.mu.RLock()
    if level < l.minLevel {
        l.mu.RUnlock()
        return
    }
    handlers := l.handlers
    fields := l.fields
    l.mu.RUnlock()

    entry := Entry{
        Level:     level,
        Message:   fmt.Sprintf(msg, args...),
        Timestamp: time.Now(),
        Fields:    fields,
    }

    for _, h := range handlers {
        h.Handle(entry)
    }
}

func (l *Logger) Debug(msg string, args ...any) { l.log(LevelDebug, msg, args...) }
func (l *Logger) Info(msg string, args ...any)  { l.log(LevelInfo, msg, args...) }
func (l *Logger) Warn(msg string, args ...any)  { l.log(LevelWarn, msg, args...) }
func (l *Logger) Error(msg string, args ...any) { l.log(LevelError, msg, args...) }

func main() {
    // Create logger with console handler
    log := New().
        AddHandler(NewConsoleHandler()).
        SetLevel(LevelDebug)

    fmt.Println("=== Basic Logging ===")
    log.Debug("Starting application")
    log.Info("Server started on port %d", 8080)
    log.Warn("Memory usage high: %d%%", 85)
    log.Error("Failed to connect: %s", "timeout")

    // Logger with fields
    fmt.Println("\n=== With Context Fields ===")
    userLog := log.With("user_id", "u123").With("request_id", "req-456")
    userLog.Info("User logged in")
    userLog.Info("Processing order")

    // JSON handler
    fmt.Println("\n=== JSON Format ===")
    jsonLog := New().
        AddHandler(NewJSONHandler(os.Stdout)).
        SetLevel(LevelInfo)

    jsonLog.With("service", "api").Info("Request received")
    jsonLog.With("latency_ms", 42).Info("Request completed")

    // Level filtering
    fmt.Println("\n=== Level Filtering (min=Warn) ===")
    warnLog := New().
        AddHandler(NewConsoleHandler()).
        SetLevel(LevelWarn)

    warnLog.Debug("This won't appear")
    warnLog.Info("This won't appear either")
    warnLog.Warn("This will appear")
    warnLog.Error("This will appear too")
}

