package main

import (
    "context"
    "fmt"
    "sync"
    "time"
)

// Message represents a published message
type Message struct {
    Topic     string
    Payload   any
    Timestamp time.Time
}

// Subscriber receives messages via a channel
type Subscriber struct {
    ID       string
    Ch       chan Message
    Topics   map[string]bool
    mu       sync.RWMutex
}

// NewSubscriber creates a subscriber with a buffered channel
func NewSubscriber(id string, bufferSize int) *Subscriber {
    return &Subscriber{
        ID:     id,
        Ch:     make(chan Message, bufferSize),
        Topics: make(map[string]bool),
    }
}

// Topic manages subscribers
type Topic struct {
    Name        string
    Subscribers map[string]*Subscriber
    mu          sync.RWMutex
}

// NewTopic creates a new topic
func NewTopic(name string) *Topic {
    return &Topic{
        Name:        name,
        Subscribers: make(map[string]*Subscriber),
    }
}

// Broker manages topics and message routing
type Broker struct {
    topics map[string]*Topic
    mu     sync.RWMutex
}

// NewBroker creates a new broker
func NewBroker() *Broker {
    return &Broker{
        topics: make(map[string]*Topic),
    }
}

// CreateTopic creates a topic if it doesn't exist
func (b *Broker) CreateTopic(name string) *Topic {
    b.mu.Lock()
    defer b.mu.Unlock()

    if topic, exists := b.topics[name]; exists {
        return topic
    }

    topic := NewTopic(name)
    b.topics[name] = topic
    return topic
}

// Subscribe adds a subscriber to a topic
func (b *Broker) Subscribe(topicName string, sub *Subscriber) error {
    b.mu.Lock()
    topic, exists := b.topics[topicName]
    if !exists {
        topic = NewTopic(topicName)
        b.topics[topicName] = topic
    }
    b.mu.Unlock()

    topic.mu.Lock()
    topic.Subscribers[sub.ID] = sub
    topic.mu.Unlock()

    sub.mu.Lock()
    sub.Topics[topicName] = true
    sub.mu.Unlock()

    return nil
}

// Unsubscribe removes a subscriber from a topic
func (b *Broker) Unsubscribe(topicName string, sub *Subscriber) {
    b.mu.RLock()
    topic, exists := b.topics[topicName]
    b.mu.RUnlock()

    if !exists {
        return
    }

    topic.mu.Lock()
    delete(topic.Subscribers, sub.ID)
    topic.mu.Unlock()

    sub.mu.Lock()
    delete(sub.Topics, topicName)
    sub.mu.Unlock()
}

// Publish sends a message to all subscribers of a topic
func (b *Broker) Publish(topicName string, payload any) {
    b.mu.RLock()
    topic, exists := b.topics[topicName]
    b.mu.RUnlock()

    if !exists {
        return
    }

    msg := Message{
        Topic:     topicName,
        Payload:   payload,
        Timestamp: time.Now(),
    }

    topic.mu.RLock()
    subs := make([]*Subscriber, 0, len(topic.Subscribers))
    for _, sub := range topic.Subscribers {
        subs = append(subs, sub)
    }
    topic.mu.RUnlock()

    // Non-blocking send to each subscriber
    for _, sub := range subs {
        select {
        case sub.Ch <- msg:
        default:
            // Channel full, message dropped for this subscriber
            fmt.Printf("  [WARN] Dropped message for subscriber %s\n", sub.ID)
        }
    }
}

func main() {
    broker := NewBroker()

    // Create subscribers
    sub1 := NewSubscriber("sub1", 10)
    sub2 := NewSubscriber("sub2", 10)
    sub3 := NewSubscriber("sub3", 10)

    // Subscribe to topics
    broker.Subscribe("orders", sub1)
    broker.Subscribe("orders", sub2)
    broker.Subscribe("inventory", sub2)
    broker.Subscribe("inventory", sub3)

    ctx, cancel := context.WithTimeout(context.Background(), time.Second)
    defer cancel()

    // Start subscriber goroutines
    var wg sync.WaitGroup
    for _, sub := range []*Subscriber{sub1, sub2, sub3} {
        wg.Add(1)
        go func(s *Subscriber) {
            defer wg.Done()
            for {
                select {
                case msg := <-s.Ch:
                    fmt.Printf("[%s] Received on %s: %v\n", s.ID, msg.Topic, msg.Payload)
                case <-ctx.Done():
                    return
                }
            }
        }(sub)
    }

    // Publish messages
    fmt.Println("=== Publishing Messages ===")
    broker.Publish("orders", map[string]any{"order_id": 1001, "item": "Widget"})
    broker.Publish("orders", map[string]any{"order_id": 1002, "item": "Gadget"})
    broker.Publish("inventory", map[string]any{"item": "Widget", "stock": 50})

    // Give time for messages to be processed
    time.Sleep(100 * time.Millisecond)

    fmt.Println("\n=== Unsubscribe sub2 from orders ===")
    broker.Unsubscribe("orders", sub2)

    broker.Publish("orders", map[string]any{"order_id": 1003, "item": "Gizmo"})

    time.Sleep(100 * time.Millisecond)
    cancel()
    wg.Wait()
    fmt.Println("\nDone")
}

