func TestBroker_Subscribe(t *testing.T) {
    broker := NewBroker()
    sub := NewSubscriber("sub1", 10)

    err := broker.Subscribe("topic1", sub)
    if err != nil {
        t.Fatalf("Subscribe failed: %v", err)
    }

    // Verify subscription tracked
    sub.mu.RLock()
    _, subscribed := sub.Topics["topic1"]
    sub.mu.RUnlock()
    if !subscribed {
        t.Error("subscriber should track topic1")
    }

    // Subscribe to another topic
    broker.Subscribe("topic2", sub)
    sub.mu.RLock()
    count := len(sub.Topics)
    sub.mu.RUnlock()
    if count != 2 {
        t.Errorf("subscriber should have 2 topics, got %d", count)
    }
}

func TestBroker_Publish(t *testing.T) {
    broker := NewBroker()
    sub1 := NewSubscriber("sub1", 10)
    sub2 := NewSubscriber("sub2", 10)

    broker.Subscribe("orders", sub1)
    broker.Subscribe("orders", sub2)
    broker.Subscribe("inventory", sub2)

    // Publish to orders
    broker.Publish("orders", "order-payload")

    // Both should receive
    select {
    case msg := <-sub1.Ch:
        if msg.Topic != "orders" || msg.Payload != "order-payload" {
            t.Errorf("sub1 got wrong message: %+v", msg)
        }
    case <-time.After(100 * time.Millisecond):
        t.Error("sub1 should receive message")
    }

    select {
    case msg := <-sub2.Ch:
        if msg.Topic != "orders" {
            t.Errorf("sub2 got wrong topic: %s", msg.Topic)
        }
    case <-time.After(100 * time.Millisecond):
        t.Error("sub2 should receive message")
    }

    // Publish to inventory (only sub2 subscribed)
    broker.Publish("inventory", "inv-payload")

    select {
    case msg := <-sub2.Ch:
        if msg.Topic != "inventory" {
            t.Errorf("expected inventory, got %s", msg.Topic)
        }
    case <-time.After(100 * time.Millisecond):
        t.Error("sub2 should receive inventory message")
    }

    // sub1 should NOT receive inventory
    select {
    case msg := <-sub1.Ch:
        t.Errorf("sub1 should not receive: %+v", msg)
    case <-time.After(50 * time.Millisecond):
        // Expected timeout
    }
}

func TestBroker_Unsubscribe(t *testing.T) {
    broker := NewBroker()
    sub := NewSubscriber("sub1", 10)

    broker.Subscribe("topic1", sub)
    broker.Unsubscribe("topic1", sub)

    // Verify unsubscribed
    sub.mu.RLock()
    _, subscribed := sub.Topics["topic1"]
    sub.mu.RUnlock()
    if subscribed {
        t.Error("subscriber should not track topic1 after unsubscribe")
    }

    // Publish should not deliver
    broker.Publish("topic1", "payload")
    select {
    case <-sub.Ch:
        t.Error("should not receive after unsubscribe")
    case <-time.After(50 * time.Millisecond):
        // Expected
    }
}

func TestBroker_NonBlockingPublish(t *testing.T) {
    broker := NewBroker()
    // Subscriber with tiny buffer
    sub := NewSubscriber("sub1", 1)
    broker.Subscribe("topic1", sub)

    // Fill the buffer
    broker.Publish("topic1", "msg1")
    // This should not block (message dropped)
    broker.Publish("topic1", "msg2")
    broker.Publish("topic1", "msg3")

    // Only first message should be in buffer
    select {
    case msg := <-sub.Ch:
        if msg.Payload != "msg1" {
            t.Errorf("expected msg1, got %v", msg.Payload)
        }
    default:
        t.Error("buffer should have msg1")
    }

    // Buffer should be empty (msg2, msg3 dropped)
    select {
    case msg := <-sub.Ch:
        t.Errorf("buffer should be empty, got %v", msg.Payload)
    default:
        // Expected
    }
}

package main

import (
    "errors"
    "fmt"
    "sync"
    "time"
)

var ErrCircuitOpen = errors.New("circuit breaker is open")

// State represents circuit breaker state
type State int

const (
    StateClosed State = iota
    StateOpen
    StateHalfOpen
)

func (s State) String() string {
    return []string{"CLOSED", "OPEN", "HALF-OPEN"}[s]
}

// CircuitBreaker implements the circuit breaker pattern
type CircuitBreaker struct {
    name           string
    maxFailures    int
    timeout        time.Duration
    halfOpenMax    int

    state          State
    failures       int
    successes      int
    lastFailure    time.Time
    halfOpenCount  int
    mu             sync.Mutex
}

// NewCircuitBreaker creates a circuit breaker
func NewCircuitBreaker(name string, maxFailures int, timeout time.Duration) *CircuitBreaker {
    return &CircuitBreaker{
        name:        name,
        maxFailures: maxFailures,
        timeout:     timeout,
        halfOpenMax: 3,  // Test with 3 requests in half-open
        state:       StateClosed,
    }
}

// Execute runs the given function through the circuit breaker
func (cb *CircuitBreaker) Execute(fn func() error) error {
    cb.mu.Lock()

    // Check if we should transition from Open to Half-Open
    if cb.state == StateOpen {
        if time.Since(cb.lastFailure) > cb.timeout {
            cb.toHalfOpen()
        } else {
            cb.mu.Unlock()
            return ErrCircuitOpen
        }
    }

    // In Half-Open, limit test requests
    if cb.state == StateHalfOpen && cb.halfOpenCount >= cb.halfOpenMax {
        cb.mu.Unlock()
        return ErrCircuitOpen
    }

    if cb.state == StateHalfOpen {
        cb.halfOpenCount++
    }
    cb.mu.Unlock()

    // Execute the function
    err := fn()

    cb.mu.Lock()
    defer cb.mu.Unlock()

    if err != nil {
        cb.onFailure()
        return err
    }

    cb.onSuccess()
    return nil
}

func (cb *CircuitBreaker) onSuccess() {
    switch cb.state {
    case StateClosed:
        cb.failures = 0  // Reset on success
    case StateHalfOpen:
        cb.successes++
        if cb.successes >= cb.halfOpenMax {
            cb.toClosed()
        }
    }
}

func (cb *CircuitBreaker) onFailure() {
    switch cb.state {
    case StateClosed:
        cb.failures++
        if cb.failures >= cb.maxFailures {
            cb.toOpen()
        }
    case StateHalfOpen:
        cb.toOpen()
    }
}

func (cb *CircuitBreaker) toClosed() {
    cb.state = StateClosed
    cb.failures = 0
    cb.successes = 0
    fmt.Printf("  [%s] State: %s -> CLOSED (recovered)\n", cb.name, StateHalfOpen)
}

func (cb *CircuitBreaker) toOpen() {
    prev := cb.state
    cb.state = StateOpen
    cb.lastFailure = time.Now()
    fmt.Printf("  [%s] State: %s -> OPEN (tripped)\n", cb.name, prev)
}

func (cb *CircuitBreaker) toHalfOpen() {
    cb.state = StateHalfOpen
    cb.halfOpenCount = 0
    cb.successes = 0
    fmt.Printf("  [%s] State: OPEN -> HALF-OPEN (testing)\n", cb.name)
}

// State returns current state
func (cb *CircuitBreaker) State() State {
    cb.mu.Lock()
    defer cb.mu.Unlock()
    return cb.state
}

func main() {
    // Circuit breaker: trips after 3 failures, 500ms timeout
    cb := NewCircuitBreaker("api-service", 3, 500*time.Millisecond)

    // Simulate function that fails
    failCount := 0
    call := func(shouldFail bool) error {
        if shouldFail {
            failCount++
            return errors.New("service unavailable")
        }
        return nil
    }

    fmt.Println("=== Initial: Circuit Closed ===")
    fmt.Printf("State: %s\n\n", cb.State())

    fmt.Println("=== Simulate Failures to Trip Circuit ===")
    for i := 1; i <= 5; i++ {
        err := cb.Execute(func() error { return call(true) })
        if err == ErrCircuitOpen {
            fmt.Printf("Request %d: BLOCKED (circuit open)\n", i)
        } else {
            fmt.Printf("Request %d: FAILED (%v)\n", i, err)
        }
    }

    fmt.Printf("\nState: %s\n", cb.State())

    fmt.Println("\n=== Requests While Open ===")
    for i := 1; i <= 2; i++ {
        err := cb.Execute(func() error { return call(false) })
        if err == ErrCircuitOpen {
            fmt.Printf("Request %d: BLOCKED\n", i)
        }
    }

    fmt.Println("\n=== Wait for Timeout ===")
    time.Sleep(600 * time.Millisecond)

    fmt.Println("\n=== Test Requests in Half-Open ===")
    for i := 1; i <= 4; i++ {
        err := cb.Execute(func() error { return call(false) })  // Success
        if err == nil {
            fmt.Printf("Request %d: SUCCESS\n", i)
        } else if err == ErrCircuitOpen {
            fmt.Printf("Request %d: BLOCKED (max test reached)\n", i)
        }
    }

    fmt.Printf("\nFinal State: %s\n", cb.State())
}

package main

import (
    "errors"
    "testing"
    "time"
)

func TestCircuitBreaker_TripsAfterFailures(t *testing.T) {
    cb := NewCircuitBreaker("test", 3, 100*time.Millisecond)
    fail := func() error { return errors.New("fail") }

    // Execute 3 failures to trip the circuit
    for i := 0; i < 3; i++ {
        cb.Execute(fail)
    }

    if cb.State() != StateOpen {
        t.Errorf("Expected StateOpen after 3 failures, got %v", cb.State())
    }

    // Further calls should be blocked
    err := cb.Execute(func() error { return nil })
    if err != ErrCircuitOpen {
        t.Errorf("Expected ErrCircuitOpen, got %v", err)
    }
}

func TestCircuitBreaker_Recovery(t *testing.T) {
    cb := NewCircuitBreaker("test", 2, 50*time.Millisecond)
    fail := func() error { return errors.New("fail") }
    succeed := func() error { return nil }

    // Trip the circuit
    cb.Execute(fail)
    cb.Execute(fail)

    if cb.State() != StateOpen {
        t.Fatal("Expected StateOpen after 2 failures")
    }

    // Wait for timeout to allow half-open
    time.Sleep(60 * time.Millisecond)

    // First success transitions to half-open
    cb.Execute(succeed)
    if cb.State() != StateHalfOpen {
        t.Errorf("Expected StateHalfOpen, got %v", cb.State())
    }

    // More successes close the circuit
    cb.Execute(succeed)
    cb.Execute(succeed)

    if cb.State() != StateClosed {
        t.Errorf("Expected StateClosed after 3 successes, got %v", cb.State())
    }
}

func TestCircuitBreaker_HalfOpenFailure(t *testing.T) {
    cb := NewCircuitBreaker("test", 1, 50*time.Millisecond)
    fail := func() error { return errors.New("fail") }

    // Trip the circuit
    cb.Execute(fail)
    time.Sleep(60 * time.Millisecond)

    // Failure in half-open goes back to open
    cb.Execute(fail)

    if cb.State() != StateOpen {
        t.Errorf("Expected StateOpen after failure in HalfOpen, got %v", cb.State())
    }
}

// ExecuteWithFallback runs the function or fallback if circuit is open
func (cb *CircuitBreaker) ExecuteWithFallback(
    fn func() (any, error),
    fallback func() any,
) (any, error) {
    result, err := cb.ExecuteReturning(fn)
    if err == ErrCircuitOpen && fallback != nil {
        return fallback(), nil  // Graceful degradation
    }
    return result, err
}

// Usage: return cached price when pricing service is down
result, _ := cb.ExecuteWithFallback(
    func() (any, error) { return pricingService.GetPrice(itemID) },
    func() any { return cachedPrices[itemID] },
)

package main

import (
    "errors"
    "fmt"
    "time"
)

// Domain errors: define at domain level, not as infrastructure details
var (
    ErrInsufficientFunds = errors.New("insufficient funds")
    ErrInvalidAmount     = errors.New("amount must be positive")
    ErrAccountInactive   = errors.New("account is inactive")
)

// Money is a value object: immutable, compared by value
type Money struct {
    amount   int64  // cents to avoid float precision issues
    currency string
}

func NewMoney(amount int64, currency string) Money {
    return Money{amount: amount, currency: currency}
}

func (m Money) Add(other Money) (Money, error) {
    if m.currency != other.currency {
        return Money{}, errors.New("currency mismatch")
    }
    return Money{amount: m.amount + other.amount, currency: m.currency}, nil
}

func (m Money) Subtract(other Money) (Money, error) {
    if m.currency != other.currency {
        return Money{}, errors.New("currency mismatch")
    }
    return Money{amount: m.amount - other.amount, currency: m.currency}, nil
}

func (m Money) IsNegative() bool { return m.amount < 0 }
func (m Money) String() string   { return fmt.Sprintf("%.2f %s", float64(m.amount)/100, m.currency) }

// Account is a domain entity: has identity, contains business rules
type Account struct {
    ID        string
    OwnerName string
    Balance   Money
    Active    bool
    CreatedAt time.Time
}

// Withdraw encapsulates business rule: can only withdraw from active account with sufficient funds
func (a *Account) Withdraw(amount Money) error {
    if !a.Active {
        return ErrAccountInactive
    }
    if amount.amount <= 0 {
        return ErrInvalidAmount
    }
    newBalance, err := a.Balance.Subtract(amount)
    if err != nil {
        return err
    }
    if newBalance.IsNegative() {
        return ErrInsufficientFunds
    }
    a.Balance = newBalance
    return nil
}

// Deposit encapsulates business rule: can only deposit to active account
func (a *Account) Deposit(amount Money) error {
    if !a.Active {
        return ErrAccountInactive
    }
    if amount.amount <= 0 {
        return ErrInvalidAmount
    }
    newBalance, err := a.Balance.Add(amount)
    if err != nil {
        return err
    }
    a.Balance = newBalance
    return nil
}

func main() {
    // Domain logic works without any infrastructure
    account := &Account{
        ID:        "acc-123",
        OwnerName: "Alice",
        Balance:   NewMoney(10000, "USD"),  // $100.00
        Active:    true,
        CreatedAt: time.Now(),
    }

    fmt.Printf("Account: %s\n", account.OwnerName)
    fmt.Printf("Balance: %s\n", account.Balance)

    // Test business rules
    if err := account.Withdraw(NewMoney(3000, "USD")); err != nil {
        fmt.Printf("Withdraw failed: %v\n", err)
    } else {
        fmt.Printf("After $30 withdrawal: %s\n", account.Balance)
    }

    if err := account.Withdraw(NewMoney(10000, "USD")); err != nil {
        fmt.Printf("Withdraw $100 failed: %v\n", err)
    }

    // Deactivate and try again
    account.Active = false
    if err := account.Deposit(NewMoney(5000, "USD")); err != nil {
        fmt.Printf("Deposit to inactive: %v\n", err)
    }
}

package main

import (
    "context"
    "errors"
    "fmt"
    "time"
)

// Domain (simplified from previous example)
type Money struct {
    amount   int64
    currency string
}

func NewMoney(amount int64, currency string) Money {
    return Money{amount: amount, currency: currency}
}

func (m Money) String() string { return fmt.Sprintf("%.2f %s", float64(m.amount)/100, m.currency) }

type Account struct {
    ID        string
    OwnerName string
    Balance   Money
    Active    bool
}

// Repository interface: defined by use case, implemented by adapter
// This is a "port" in hexagonal architecture terminology
type AccountRepository interface {
    FindByID(ctx context.Context, id string) (*Account, error)
    Save(ctx context.Context, account *Account) error
}

// TransferUseCase orchestrates a money transfer between accounts
type TransferUseCase struct {
    repo AccountRepository
}

func NewTransferUseCase(repo AccountRepository) *TransferUseCase {
    return &TransferUseCase{repo: repo}
}

// Execute performs the transfer: application logic, not domain logic
func (uc *TransferUseCase) Execute(ctx context.Context, fromID, toID string, amount Money) error {
    // Load accounts
    fromAccount, err := uc.repo.FindByID(ctx, fromID)
    if err != nil {
        return fmt.Errorf("find source account: %w", err)
    }
    toAccount, err := uc.repo.FindByID(ctx, toID)
    if err != nil {
        return fmt.Errorf("find destination account: %w", err)
    }

    // Validate
    if !fromAccount.Active || !toAccount.Active {
        return errors.New("both accounts must be active")
    }
    if fromAccount.Balance.amount < amount.amount {
        return errors.New("insufficient funds")
    }

    // Perform transfer (domain logic would be in Account methods)
    fromAccount.Balance.amount -= amount.amount
    toAccount.Balance.amount += amount.amount

    // Persist
    if err := uc.repo.Save(ctx, fromAccount); err != nil {
        return fmt.Errorf("save source account: %w", err)
    }
    if err := uc.repo.Save(ctx, toAccount); err != nil {
        return fmt.Errorf("save destination account: %w", err)
    }

    return nil
}

// In-memory repository: adapter implementing the port
type InMemoryAccountRepo struct {
    accounts map[string]*Account
}

func NewInMemoryAccountRepo() *InMemoryAccountRepo {
    return &InMemoryAccountRepo{accounts: make(map[string]*Account)}
}

func (r *InMemoryAccountRepo) FindByID(ctx context.Context, id string) (*Account, error) {
