package main

import (
    "context"
    "encoding/json"
    "errors"
    "fmt"
    "net/http"
)

// Domain
type Money struct {
    amount   int64
    currency string
}

func NewMoney(amount int64, currency string) Money {
    return Money{amount: amount, currency: currency}
}

type Account struct {
    ID      string
    Balance Money
    Active  bool
}

var ErrInsufficientFunds = errors.New("insufficient funds")
var ErrAccountNotFound = errors.New("account not found")
var ErrAccountInactive = errors.New("account is inactive")

// Port: repository interface defined by use case layer
type AccountRepository interface {
    FindByID(ctx context.Context, id string) (*Account, error)
    Save(ctx context.Context, account *Account) error
}

// Use Case
type TransferUseCase struct {
    repo AccountRepository
}

func NewTransferUseCase(repo AccountRepository) *TransferUseCase {
    return &TransferUseCase{repo: repo}
}

func (uc *TransferUseCase) Execute(ctx context.Context, fromID, toID string, amount Money) error {
    from, err := uc.repo.FindByID(ctx, fromID)
    if err != nil {
        return err
    }
    to, err := uc.repo.FindByID(ctx, toID)
    if err != nil {
        return err
    }
    if !from.Active || !to.Active {
        return ErrAccountInactive
    }
    if from.Balance.amount < amount.amount {
        return ErrInsufficientFunds
    }
    from.Balance.amount -= amount.amount
    to.Balance.amount += amount.amount
    if err := uc.repo.Save(ctx, from); err != nil {
        return err
    }
    return uc.repo.Save(ctx, to)
}

// HTTP Adapter: translates HTTP requests to use case calls
type TransferHandler struct {
    transferUC *TransferUseCase
}

func NewTransferHandler(uc *TransferUseCase) *TransferHandler {
    return &TransferHandler{transferUC: uc}
}

// DTO: Data Transfer Object for HTTP request
type TransferRequest struct {
    FromAccountID string `json:"from_account_id"`
    ToAccountID   string `json:"to_account_id"`
    Amount        int64  `json:"amount"`
    Currency      string `json:"currency"`
}

// HTTP handler method
func (h *TransferHandler) ServeHTTP(w http.ResponseWriter, r *http.Request) {
    if r.Method != http.MethodPost {
        http.Error(w, "method not allowed", http.StatusMethodNotAllowed)
        return
    }

    var req TransferRequest
    if err := json.NewDecoder(r.Body).Decode(&req); err != nil {
        http.Error(w, "invalid request body", http.StatusBadRequest)
        return
    }

    // Convert DTO to domain object
    amount := NewMoney(req.Amount, req.Currency)

    // Call use case
    err := h.transferUC.Execute(r.Context(), req.FromAccountID, req.ToAccountID, amount)
    if err != nil {
        // Map domain errors to HTTP status codes
        switch {
        case errors.Is(err, ErrAccountNotFound):
            http.Error(w, err.Error(), http.StatusNotFound)
        case errors.Is(err, ErrInsufficientFunds), errors.Is(err, ErrAccountInactive):
            http.Error(w, err.Error(), http.StatusUnprocessableEntity)
        default:
            http.Error(w, "internal error", http.StatusInternalServerError)
        }
        return
    }

    w.WriteHeader(http.StatusOK)
    json.NewEncoder(w).Encode(map[string]string{"status": "transferred"})
}

// In-memory adapter (for demonstration)
type InMemoryAccountRepo struct {
    accounts map[string]*Account
}

func NewInMemoryAccountRepo() *InMemoryAccountRepo {
    return &InMemoryAccountRepo{accounts: make(map[string]*Account)}
}

func (r *InMemoryAccountRepo) FindByID(ctx context.Context, id string) (*Account, error) {
    if acc, ok := r.accounts[id]; ok {
        return acc, nil
    }
    return nil, ErrAccountNotFound
}

func (r *InMemoryAccountRepo) Save(ctx context.Context, acc *Account) error {
    r.accounts[acc.ID] = acc
    return nil
}

func main() {
    // Wire up: adapters -> use cases -> domain
    repo := NewInMemoryAccountRepo()
    transferUC := NewTransferUseCase(repo)
    handler := NewTransferHandler(transferUC)

    // Seed data
    repo.Save(context.Background(), &Account{ID: "1", Balance: NewMoney(10000, "USD"), Active: true})
    repo.Save(context.Background(), &Account{ID: "2", Balance: NewMoney(5000, "USD"), Active: true})

    // Print initial state
    acc1, _ := repo.FindByID(context.Background(), "1")
    acc2, _ := repo.FindByID(context.Background(), "2")
    fmt.Printf("Before: Account 1: %d cents, Account 2: %d cents\n", acc1.Balance.amount, acc2.Balance.amount)

    // Simulate HTTP request (in real app, use http.ListenAndServe)
    fmt.Println("\nHandler registered at POST /transfer")
    fmt.Printf("Handler type: %T\n", handler)

    // Direct use case call for demo
    err := transferUC.Execute(context.Background(), "1", "2", NewMoney(3000, "USD"))
    if err != nil {
        fmt.Printf("Transfer failed: %v\n", err)
        return
    }

    acc1, _ = repo.FindByID(context.Background(), "1")
    acc2, _ = repo.FindByID(context.Background(), "2")
    fmt.Printf("After: Account 1: %d cents, Account 2: %d cents\n", acc1.Balance.amount, acc2.Balance.amount)
}

