// Table-driven test structure
type updateEmailTest struct {
    name        string
    userID      string
    newEmail    string
    stubUser    *User
    findError   error
    saveError   error
    expectError string  // empty means expect success
}

func main() {
    tests := []updateEmailTest{
        {
            name:     "success",
            userID:   "1",
            newEmail: "new@example.com",
            stubUser: &User{ID: "1", Name: "Test", Email: "old@example.com"},
        },
        {
            name:        "invalid email",
            userID:      "1",
            newEmail:    "invalid",
            stubUser:    &User{ID: "1", Name: "Test", Email: "old@example.com"},
            expectError: "invalid email",
        },
