            userID:      "1",
            newEmail:    "new@example.com",
            stubUser:    &User{ID: "1", Name: "Test", Email: "old@example.com"},
            saveError:   errors.New("db error"),
            expectError: "db error",
        },
    }

    fmt.Println("=== Table-Driven Tests ===")
    for _, tc := range tests {
        // Setup
        repo := &StubUserRepo{
            User:      tc.stubUser,
            FindError: tc.findError,
            SaveError: tc.saveError,
        }
        svc := &UserService{repo: repo}

        // Execute
        err := svc.UpdateEmail(context.Background(), tc.userID, tc.newEmail)

        // Verify
        if tc.expectError != "" {
            if err == nil {
                fmt.Printf("FAIL %s: expected error containing %q, got nil\n",
                    tc.name, tc.expectError)
            } else if !strings.Contains(err.Error(), tc.expectError) {
                fmt.Printf("FAIL %s: expected error containing %q, got %q\n",
                    tc.name, tc.expectError, err.Error())
            } else {
                fmt.Printf("PASS %s: got expected error\n", tc.name)
            }
        } else {
            if err != nil {
                fmt.Printf("FAIL %s: unexpected error: %v\n", tc.name, err)
            } else {
                fmt.Printf("PASS %s\n", tc.name)
            }
        }
    }
}

package main

import "fmt"

// Strategy interface
type PaymentStrategy interface {
    Pay(amount float64) (string, error)
}

// Real implementation
type CreditCardPayment struct {
    CardNumber string
}

func (c CreditCardPayment) Pay(amount float64) (string, error) {
    return fmt.Sprintf("Charged $%.2f to card %s", amount, c.CardNumber[12:]), nil
}

// Test double: records calls, returns configured result
type MockPayment struct {
    Calls     []float64
    ReturnMsg string
    ReturnErr error
}

func (m *MockPayment) Pay(amount float64) (string, error) {
    m.Calls = append(m.Calls, amount)
    return m.ReturnMsg, m.ReturnErr
}

// Service that uses strategy
type Checkout struct {
    payment PaymentStrategy
}

func (c *Checkout) Process(items []float64) (string, error) {
    var total float64
    for _, item := range items {
        total += item
    }
    return c.payment.Pay(total)
}

func main() {
    fmt.Println("=== Testing Strategy Pattern ===")

    // Test 1: Verify total is calculated correctly
    mock := &MockPayment{ReturnMsg: "success"}
    checkout := &Checkout{payment: mock}

    _, _ = checkout.Process([]float64{10.0, 20.0, 30.0})

    if len(mock.Calls) != 1 {
        fmt.Printf("FAIL: expected 1 call, got %d\n", len(mock.Calls))
    } else if mock.Calls[0] != 60.0 {
        fmt.Printf("FAIL: expected 60.0, got %.2f\n", mock.Calls[0])
    } else {
        fmt.Printf("PASS: Pay called with correct total: $%.2f\n", mock.Calls[0])
    }

    // Test 2: Real strategy works
    real := CreditCardPayment{CardNumber: "4111111111111234"}
    checkout2 := &Checkout{payment: real}
    msg, err := checkout2.Process([]float64{99.99})

    if err != nil {
        fmt.Printf("FAIL: unexpected error: %v\n", err)
    } else {
        fmt.Printf("PASS: Real payment: %s\n", msg)
    }

    // Test 3: Empty cart
    mock2 := &MockPayment{ReturnMsg: "ok"}
    checkout3 := &Checkout{payment: mock2}
    _, _ = checkout3.Process([]float64{})

    if mock2.Calls[0] != 0.0 {
        fmt.Printf("FAIL: empty cart should total 0\n")
    } else {
        fmt.Println("PASS: Empty cart totals $0.00")
    }
}

