    }

    return nil
}

// GOOD: Testable - receives dependencies via interfaces
type Database interface {
    SaveOrder(userID string, items []string) error
}

type PaymentGateway interface {
    Charge(userID string, amount float64) error
}

type Clock interface {
    Now() time.Time
}

type GoodOrderService struct {
    db      Database
    payment PaymentGateway
    clock   Clock
}

func NewOrderService(db Database, payment PaymentGateway, clock Clock) *GoodOrderService {
    return &GoodOrderService{db: db, payment: payment, clock: clock}
}

func (s *GoodOrderService) PlaceOrder(userID string, items []string) error {
    // Uses injected clock - tests can control time
    if s.clock.Now().Hour() < 9 {
        return fmt.Errorf("orders not accepted before 9am")
    }

    // Uses injected payment - tests use mock
    if err := s.payment.Charge(userID, 99.99); err != nil {
        return fmt.Errorf("payment failed: %w", err)
    }

    // Uses injected database - tests use fake
    return s.db.SaveOrder(userID, items)
}

// Test doubles for the good design
type MockClock struct{ FixedTime time.Time }
func (c MockClock) Now() time.Time { return c.FixedTime }

type MockPayment struct{ ShouldFail bool }
func (p MockPayment) Charge(userID string, amount float64) error {
    if p.ShouldFail {
        return fmt.Errorf("card declined")
    }
    return nil
}

type FakeDB struct{ Orders []string }
func (d *FakeDB) SaveOrder(userID string, items []string) error {
