    db := &FakeDB{}
    svc = NewOrderService(db, MockPayment{}, clock)

    err = svc.PlaceOrder("user-2", []string{"item-2"})
    if err == nil && len(db.Orders) == 1 {
        fmt.Println("Test 2 PASS: Order placed at 10am")
    }

    // Test: payment failure handled
    svc = NewOrderService(&FakeDB{}, MockPayment{ShouldFail: true}, clock)
    err = svc.PlaceOrder("user-3", []string{"item-3"})
    if err != nil {
        fmt.Println("Test 3 PASS: Payment failure handled:", err)
    }
