    }

    for _, tt := range tests {
        t.Run(tt.name, func(t *testing.T) {
            // Arrange
            mock := &MockSender{ReturnErr: tt.senderErr}
            svc := &EmailService{sender: mock}

            // Act
            err := svc.SendWelcome(context.Background(), tt.email)

            // Assert
            if (err != nil) != tt.wantErr {
                t.Errorf("SendWelcome() error = %v, wantErr %v", err, tt.wantErr)
            }
            if len(mock.Calls) != tt.wantCalls {
                t.Errorf("SendWelcome() calls = %d, want %d", len(mock.Calls), tt.wantCalls)
            }
        })
    }
}

// Run tests manually for demonstration
func main() {
    fmt.Println("Running tests (simulated go test output):")
    fmt.Println()

    tests := []struct {
        name      string
        email     string
        senderErr error
        wantErr   bool
        wantCalls int
    }{
        {"valid email sends successfully", "user@example.com", nil, false, 1},
        {"invalid email rejected before sending", "invalid", nil, true, 0},
        {"sender failure propagates error", "user@example.com", errors.New("SMTP error"), true, 1},
    }

    passed := 0
    for _, tt := range tests {
        mock := &MockSender{ReturnErr: tt.senderErr}
        svc := &EmailService{sender: mock}
        err := svc.SendWelcome(context.Background(), tt.email)

        errOk := (err != nil) == tt.wantErr
        callsOk := len(mock.Calls) == tt.wantCalls

        if errOk && callsOk {
            fmt.Printf("    --- PASS: TestEmailService_SendWelcome/%s\n", strings.ReplaceAll(tt.name, " ", "_"))
            passed++
        } else {
            fmt.Printf("    --- FAIL: TestEmailService_SendWelcome/%s\n", strings.ReplaceAll(tt.name, " ", "_"))
        }
    }
