import "sort"

func contains(nums []int, target int) bool {
    // Find where target would be inserted
    idx := sort.Search(len(nums), func(i int) bool {
        return nums[i] >= target
    })
    // Check if we found it (not past end, and value matches)
    return idx < len(nums) && nums[idx] == target
}

nums := []int{1, 3, 5, 7, 9}
fmt.Println(contains(nums, 5))   // true
