// Interview style: use nil slice
func twoSum(nums []int, target int) []int {
    // var result []int would also work
    seen := make(map[int]int)
    for i, n := range nums {
        if j, ok := seen[target-n]; ok {
            return []int{j, i}  // Return literal when found
        }
        seen[n] = i
    }
    return nil  // Return nil when not found
}

